#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

class MigrationRunner {
    constructor(migrationsDir = './migrations') {
        this.migrationsDir = migrationsDir;
    }

    /**
     * Get all SQL files from migrations directory sorted by filename
     * @returns {Array} Array of migration file objects with name and path
     */
    getMigrationFiles() {
        try {
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for .sql files and sort them
            const sqlFiles = files
                .filter(file => file.endsWith('.sql'))
                .sort((a, b) => {
                    // Extract numeric prefixes for sorting
                    const numA = parseInt(a.match(/^\d+/)?.[0] || '0');
                    const numB = parseInt(b.match(/^\d+/)?.[0] || '0');
                    return numA - numB;
                })
                .map(file => ({
                    name: file,
                    path: path.join(this.migrationsDir, file)
                }));

            return sqlFiles;
        } catch (error) {
            if (error.code === 'ENOENT') {
                console.error(`Error: Migrations directory "${this.migrationsDir}" not found.`);
            } else {
                console.error(`Error reading migrations directory: ${error.message}`);
            }
            return [];
        }
    }

    /**
     * Read the content of a migration file
     * @param {string} filePath - Path to the migration file
     * @returns {string} The SQL content of the file
     */
    readMigrationFile(filePath) {
        try {
            return fs.readFileSync(filePath, 'utf8');
        } catch (error) {
            console.error(`Error reading migration file ${filePath}: ${error.message}`);
            return '';
        }
    }

    /**
     * Log migration files that would be applied
     */
    logMigrations() {
        console.log('=== Database Migration Script ===');
        console.log(`Reading migrations from: ${this.migrationsDir}`);
        console.log('-----------------------------------');

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migration files found.');
            return;
        }

        console.log(`Found ${migrationFiles.length} migration file(s):\n`);

        migrationFiles.forEach((file, index) => {
            console.log(`${index + 1}. ${file.name}`);
        });

        console.log('\n-----------------------------------');
        console.log(`Total migrations to apply: ${migrationFiles.length}`);
    }

    /**
     * Main entry point
     */
    run() {
        this.logMigrations();
    }
}

// If this script is run directly (not imported as a module)
if (require.main === module) {
    const migrationsDir = process.argv[2] || './migrations';
    const runner = new MigrationRunner(migrationsDir);
    runner.run();
}

module.exports = MigrationRunner;

