 * @returns {Object} Parsed database URL components
 */
parseDatabaseUrl(url) {
    try {
        // Parse database URL format: protocol://username:password@host:port/database
        const urlPattern = /^(\w+):\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
        const match = url.match(urlPattern);

        if (match) {
            return {
                protocol: match[1],
