            databaseInfo: this.databaseUrl ? this.parseDatabaseUrl(this.databaseUrl) : null
        };

        // Stringify the data
        const postData = JSON.stringify(auditData);

        // Parse the audit URL
        const url = new URL(auditUrl);
        const options = {
            hostname: url.hostname,
            port: url.port || (url.protocol === 'https:' ? 443 : 80),
            path: url.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(postData),
                'User-Agent': 'MigrationAudit/1.0'
            }
        };

        console.log(`📤 Sending audit data to ${auditUrl}...`);

        // Use the appropriate HTTP module based on protocol
        const httpModule = url.protocol === 'https:' ? https : http;

        return new Promise((resolve, reject) => {
            const req = httpModule.request(options, (res) => {
                let responseData = '';

                res.on('data', (chunk) => {
                    responseData += chunk;
                });

                res.on('end', () => {
                    if (res.statusCode >= 200 && res.statusCode < 300) {
                        console.log(`✅ Audit data sent successfully (Status: ${res.statusCode})`);
                        try {
                            const response = JSON.parse(responseData);
                            console.log(`📊 Audit ID: ${response.auditId || 'N/A'}, Status: ${response.status || 'unknown'}`);
                        } catch (e) {
                            // Non-JSON response is okay
                        }
                        resolve(true);
                    } else {
                        console.log(`⚠ Audit service returned status: ${res.statusCode}`);
                        console.log(`Response: ${responseData}`);
                        resolve(false);
                    }
                });
            });

            req.on('error', (error) => {
                console.log(`❌ Error sending audit data: ${error.message}`);
                console.log(`   Note: This may be expected if the audit service is not running`);
                console.log(`   Migration will continue with local logging only`);
                resolve(false); // Don't reject, we want migrations to continue even if audit fails
            });

            // Set timeout for the request
            req.setTimeout(5000, () => {
                req.destroy();
                console.log('⚠ Audit request timeout (5s)');
                console.log('   Migration will continue with local logging only');
                resolve(false);
            });

            // Write data and end the request
            req.write(postData);
            req.end();
        });

    } catch (error) {
        console.error(`❌ Error preparing audit data: ${error.message}`);
        return false;
    }
}

