#!/usr/bin/env node

const http = require('http');

const PORT = 3003;
const server = http.createServer((req, res) => {
    // Only handle POST requests to /api/audit
    if (req.method === 'POST' && req.url === '/api/audit') {
        let body = '';

        req.on('data', chunk => {
            body += chunk.toString();
        });

        req.on('end', () => {
            try {
                const auditData = JSON.parse(body);

                console.log('📥 Received audit request:');
                console.log(`   Timestamp: ${auditData.timestamp}`);
                console.log(`   Environment File: ${auditData.environmentFile}`);
                console.log(`   Environment Variables: ${Object.keys(auditData.environmentVariables || {}).length} variables`);
                console.log(`   Database Info: ${auditData.databaseInfo ? 'Present' : 'Not present'}`);

                // Log some sample env vars (masking sensitive data)
                const envVars = auditData.environmentVariables || {};
                Object.entries(envVars).forEach(([key, value]) => {
                    const maskedValue = key.includes('SECRET') || key.includes('KEY') || key.includes('PASSWORD')
                        ? '***MASKED***'
                        : value.length > 50 
                            ? value.substring(0, 50) + '...' 
                            : value;
                    console.log(`   ${key}: ${maskedValue}`);
                });

                // Send success response
                res.writeHead(200, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({
                    success: true,
                    auditId: `audit_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
                    status: 'logged',
                    timestamp: new Date().toISOString(),
                    variableCount: Object.keys(envVars).length
                }));

            } catch (error) {
                console.error('Error processing audit request:', error);
                res.writeHead(400, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ error: 'Invalid JSON data' }));
            }
        });
    } else {
        res.writeHead(404, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Not found' }));
    }
});

server.listen(PORT, () => {
    console.log(`🚀 Test audit server running on http://localhost:${PORT}`);
    console.log(`📝 Endpoint: POST http://localhost:${PORT}/api/audit`);
    console.log('Press Ctrl+C to stop the server\n');
});

// Handle graceful shutdown
process.on('SIGINT', () => {
    console.log('\n🛑 Shutting down audit server...');
    server.close(() => {
        console.log('✅ Audit server stopped');
        process.exit(0);
    });
});

