/**
 * Parse .env.test file and extract DATABASE_URL
 * @returns {string|null} The DATABASE_URL or null if not found
 */
parseEnvFile() {
    try {
        // Check if .env.test file exists
        if (!fs.existsSync(this.envFilePath)) {
            console.warn(`Warning: .env.test file '${this.envFilePath}' not found.`);
            return null;
        }

        // Read the file
        const envContent = fs.readFileSync(this.envFilePath, 'utf8');

        // Parse key-value pairs
        const envLines = envContent.split('\n');

        for (const line of envLines) {
            // Skip comments and empty lines
            const trimmedLine = line.trim();
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            // Parse key=value pairs
            const equalsIndex = trimmedLine.indexOf('=');
            if (equalsIndex === -1) {
                continue; // Skip lines without '='
            }

            const key = trimmedLine.substring(0, equalsIndex).trim();
            const value = trimmedLine.substring(equalsIndex + 1).trim();

            if (key === 'DATABASE_URL') {
                return value;
            }
        }

        console.warn('Warning: DATABASE_URL not found in .env.test file.');
