#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationRunner {
    constructor() {
        this.migrationsDir = path.join(__dirname, 'migrations');
        this.envFilePath = path.join(__dirname, '.env.test');
        this.databaseUrl = null;
    }

    /**
     * Get all migration files from the migrations directory
     * @returns {Array} Sorted array of migration filenames
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Error: Migrations directory '${this.migrationsDir}' does not exist.`);
                process.exit(1);
            }

            // Read all files from the directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for .sql files only
            const sqlFiles = files.filter(file => file.endsWith('.sql'));

            // Sort files alphabetically (which should be in order)
            sqlFiles.sort();

            return sqlFiles;
        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            process.exit(1);
        }
    }

    /**
     * Log migration files in order
     * @param {Array} migrationFiles - Array of migration filenames
     */
    logMigrations(migrationFiles) {
        console.log('\n=== Database Migration Script ===\n');
        console.log(`Found ${migrationFiles.length} migration file(s) in ${this.migrationsDir}\n`);

        if (migrationFiles.length === 0) {
            console.log('No migration files to apply.');
            return;
        }

        console.log('Migration files to apply (in order):\n');

        // Log each migration file with a number
        migrationFiles.forEach((filename, index) => {
            console.log(`${index + 1}. ${filename}`);

            // Optional: Log the first line of each SQL file as a description
            try {
                const filePath = path.join(this.migrationsDir, filename);
                const content = fs.readFileSync(filePath, 'utf8');
                const firstLine = content.split('\n')[0].trim();

                if (firstLine && !firstLine.startsWith('--')) {
                    console.log(`   Description: ${firstLine}`);
                } else if (firstLine && firstLine.startsWith('--')) {
                    console.log(`   Description: ${firstLine.substring(2).trim()}`);
                }
            } catch (error) {
                // If we can't read the file, just skip the description
            }

            console.log(); // Add blank line between migrations
        });

        console.log('==================================\n');
        console.log(`To apply these migrations, you would:`);
        console.log(`1. Read each SQL file in order`);
        console.log(`2. Execute the SQL statements against your database`);
        console.log(`3. Track which migrations have been applied (not implemented in this script)`);
    }

    /**
     * Parse .env.test file and extract DATABASE_URL
     * @returns {string|null} The DATABASE_URL or null if not found
     */
    parseEnvFile() {
        try {
            // Check if .env.test file exists
            if (!fs.existsSync(this.envFilePath)) {
                console.warn(`Warning: .env.test file '${this.envFilePath}' not found.`);
                return null;
            }

            // Read the file
            const envContent = fs.readFileSync(this.envFilePath, 'utf8');

            // Parse key-value pairs
            const envLines = envContent.split('\n');

            for (const line of envLines) {
                // Skip comments and empty lines
                const trimmedLine = line.trim();
                if (!trimmedLine || trimmedLine.startsWith('#')) {
                    continue;
                }

                // Parse key=value pairs
                const equalsIndex = trimmedLine.indexOf('=');
                if (equalsIndex === -1) {
                    continue; // Skip lines without '='
                }

                const key = trimmedLine.substring(0, equalsIndex).trim();
                const value = trimmedLine.substring(equalsIndex + 1).trim();

                if (key === 'DATABASE_URL') {
                    return value;
                }
            }

            console.warn('Warning: DATABASE_URL not found in .env.test file.');
            return null;

        } catch (error) {
            console.error(`Error parsing .env.test file: ${error.message}`);
            return null;
        }
    }

    /**
     * Log connection success message based on DATABASE_URL
     */
    logConnectionSuccess() {
        this.databaseUrl = this.parseEnvFile();

        if (this.databaseUrl) {
            // Parse the database URL to extract useful information
            try {
                const url = new URL(this.databaseUrl);
                const protocol = url.protocol.replace(':', '');
                const hostname = url.hostname;
                const port = url.port || (protocol === 'postgres' ? '5432' : 'unknown');
                const database = url.pathname.substring(1); // Remove leading '/'

                // Hide password in logs
                let safeUrl = this.databaseUrl;
                if (url.password) {
                    safeUrl = this.databaseUrl.replace(url.password, '***');
                }

                console.log('✓ Successfully parsed DATABASE_URL from .env.test');
                console.log(`  Protocol: ${protocol}`);
                console.log(`  Host: ${hostname}:${port}`);
                console.log(`  Database: ${database}`);
                console.log(`  Connection string: ${safeUrl}`);
                console.log(`  (In a real implementation, this would connect to the database)\n`);

            } catch (error) {
                console.log(`✓ Successfully parsed DATABASE_URL from .env.test`);
                console.log(`  Connection string: ${this.databaseUrl.substring(0, 50)}...`);
                console.log(`  Note: Could not parse URL format, but DATABASE_URL was found\n`);
            }
        } else {
            console.log('⚠ No DATABASE_URL found in .env.test');
            console.log('  (Running in dry-run mode, migrations would not be applied)\n');
        }
    }

    /**
     * Run the migration report
     */
    run() {
        console.log('Starting migration script...\n');

        // Parse and log connection info
        this.logConnectionSuccess();

        // Get migration files
        const migrationFiles = this.getMigrationFiles();

        // Log migrations
        this.logMigrations(migrationFiles);

        console.log('Migration script completed.');
    }
}

// Run the migration script if this file is executed directly
if (require.main === module) {
    const migrationRunner = new MigrationRunner();
    migrationRunner.run();
}

// Export for testing or programmatic use
module.exports = MigrationRunner;

