                port: url.port || (url.protocol === 'https:' ? 443 : 80),
                path: url.pathname,
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Content-Length': Buffer.byteLength(postData)
                },
                timeout: 5000 // 5 second timeout
            };

            return new Promise((resolve, reject) => {
                const req = http.request(options, (res) => {
                    let responseData = '';

                    res.on('data', (chunk) => {
                        responseData += chunk;
                    });

                    res.on('end', () => {
                        try {
                            const response = JSON.parse(responseData);

                            if (res.statusCode >= 200 && res.statusCode < 300) {
                                console.log(`  ✓ Audit service responded with status ${res.statusCode}: ${response.message || 'Success'}`);
                                console.log(`  Audit ID: ${response.auditId || 'Not provided'}`);
                                resolve(true);
                            } else {
                                console.error(`  ✗ Audit service responded with error ${res.statusCode}: ${response.message || 'Unknown error'}`);
                                console.log(`  Continuing with migrations (audit failure is non-fatal)`);
                                resolve(false);
                            }
                        } catch (error) {
                            console.error(`  ✗ Failed to parse audit service response: ${error.message}`);
                            console.log(`  Continuing with migrations (audit failure is non-fatal)`);
                            resolve(false);
                        }
                    });
                });

                req.on('error', (error) => {
                    console.error(`  ✗ Failed to send audit data: ${error.message}`);
                    console.log(`  Continuing with migrations (audit failure is non-fatal)`);
                    resolve(false);
                });

                req.on('timeout', () => {
                    console.error(`  ✗ Audit request timeout after ${options.timeout}ms`);
                    console.log(`  Continuing with migrations (audit failure is non-fatal)`);
                    req.destroy();
                    resolve(false);
                });

                req.write(postData);
                req.end();
            });
        }

    } catch (error) {
        console.error(`  ✗ Failed to send audit data: ${error.message}`);
        console.log(`  Continuing with migrations (audit failure is non-fatal)`);
        return false;
    }
}

