#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL migration files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 * 
 * Usage: node migrate.js
 */

class MigrationScript {
    constructor() {
        this.migrationsDir = path.join(__dirname, 'migrations');
    }

    /**
     * Main function to run the migration script
     */
    async run() {
        try {
            console.log('=== Database Migration Script ===');
            console.log(`Reading migration files from: ${this.migrationsDir}`);

            // Get all migration files
            const migrationFiles = this.getMigrationFiles();

            if (migrationFiles.length === 0) {
                console.log('No migration files found.');
                return;
            }

            console.log(`Found ${migrationFiles.length} migration file(s):`);
            console.log('----------------------------------------');

            // Display migration files in order
            migrationFiles.forEach((file, index) => {
                console.log(`${index + 1}. ${file}`);
            });

            console.log('----------------------------------------');
            console.log('Migration files would be applied in the above order.');
            console.log('To actually apply migrations, you would need to:');
            console.log('1. Read each SQL file');
            console.log('2. Execute the SQL against your database');
            console.log('3. Track which migrations have been applied');

        } catch (error) {
            console.error('Error running migration script:', error.message);
            process.exit(1);
        }
    }

    /**
     * Get all SQL migration files from the migrations directory
     * Sorted numerically by filename prefix
     * @returns {Array<string>} Array of migration filenames
     */
    getMigrationFiles() {
        // Check if migrations directory exists
        if (!fs.existsSync(this.migrationsDir)) {
            console.warn(`Migrations directory not found: ${this.migrationsDir}`);
            console.log('Creating migrations directory...');
            fs.mkdirSync(this.migrationsDir, { recursive: true });
            return [];
        }

        // Read all files from migrations directory
        const files = fs.readdirSync(this.migrationsDir);

        // Filter for SQL files and sort them
        const migrationFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort((a, b) => {
                // Extract numeric prefix from filename (e.g., "001_" from "001_create_users.sql")
                const numA = this.extractNumberFromFilename(a);
                const numB = this.extractNumberFromFilename(b);
                return numA - numB;
            });

        return migrationFiles;
    }

    /**
     * Extract numeric prefix from filename
     * @param {string} filename 
     * @returns {number} Extracted number or Infinity if not found
     */
    extractNumberFromFilename(filename) {
        // Try to extract numbers from the beginning of the filename
        const match = filename.match(/^(\d+)/);
        return match ? parseInt(match[1], 10) : Infinity;
    }

    /**
     * (Optional) Read and display SQL content for a file
     * @param {string} filename 
     * @returns {string} SQL content
     */
    readMigrationContent(filename) {
        const filePath = path.join(this.migrationsDir, filename);
        return fs.readFileSync(filePath, 'utf8');
    }
}

// Run the script if this file is executed directly
if (require.main === module) {
    const migrationScript = new MigrationScript();
    migrationScript.run();
}

module.exports = MigrationScript;

