/**
 * Load database configuration from .env.test file
 * Extracts DATABASE_URL and logs successful connection
 */
loadDatabaseConfig() {
    try {
        // Check if .env.test file exists
        if (!fs.existsSync(this.envFilePath)) {
            console.warn(`Warning: Environment file not found: ${this.envFilePath}`);
            console.log('Using default configuration...');
            return;
        }

        // Read the .env.test file
        const envContent = fs.readFileSync(this.envFilePath, 'utf8');

        // Parse the file to find DATABASE_URL
        const lines = envContent.split('\n');
        let databaseUrlLine = null;

        for (const line of lines) {
            // Skip comments and empty lines
            if (line.trim().startsWith('#') || line.trim() === '') {
                continue;
            }

            // Check if this line contains DATABASE_URL
            if (line.includes('DATABASE_URL=')) {
                databaseUrlLine = line;
                break;
            }
        }

        if (databaseUrlLine) {
            // Extract the DATABASE_URL value
            const match = databaseUrlLine.match(/DATABASE_URL=(.+)/);
            if (match && match[1]) {
                this.databaseUrl = match[1].trim();

                // Parse the connection string to get components
                const urlParts = this.parseDatabaseUrl(this.databaseUrl);

                // Log successful connection message
                console.log('✅ Successfully loaded database configuration:');
                console.log(`   Protocol: ${urlParts.protocol}`);
                console.log(`   Username: ${urlParts.username}`);
                console.log(`   Host: ${urlParts.host}`);
                console.log(`   Port: ${urlParts.port}`);
                console.log(`   Database: ${urlParts.database}`);
                console.log(`   Connection would be established to: ${urlParts.host}:${urlParts.port}`);
            }
        } else {
            console.warn('Warning: DATABASE_URL not found in .env.test file');
            console.log('Using default configuration...');
        }

    } catch (error) {
        console.warn(`Warning: Could not load database configuration: ${error.message}`);
        console.log('Using default configuration...');
    }
}

/**
 * Parse database URL to extract components
 * @param {string} databaseUrl - The database connection string
 * @returns {Object} Parsed URL components
 */
parseDatabaseUrl(databaseUrl) {
    try {
        // Use URL parsing if it's a valid URL
        const url = new URL(databaseUrl);

        return {
            protocol: url.protocol.replace(':', ''),
            username: url.username || 'unknown',
            host: url.hostname || 'unknown',
            port: url.port || '5432', // Default PostgreSQL port
            database: url.pathname ? url.pathname.substring(1) : 'unknown'
        };
    } catch (error) {
        // Fallback parsing for non-standard URLs
        const pattern = /^([^:]+):\/\/([^:@]+):?([^@]*)@([^:]+):?(\d*)\/(.+)$/;
        const match = databaseUrl.match(pattern);

        if (match) {
            return {
                protocol: match[1],
                username: match[2],
                password: '***', // Hide password for security
                host: match[4],
                port: match[5] || '5432',
                database: match[6]
            };
        }

        // Return minimal info if parsing fails
        return {
            protocol: 'unknown',
            username: 'unknown',
            host: 'unknown',
            port: 'unknown',
            database: 'unknown'
        };
    }
}

