/**
 * Send audit log to compliance service
 * @param {Object} envConfig - Environment configuration object
 */
async sendAuditLog(envConfig) {
    const auditUrl = 'http://localhost:3003/api/audit';

    // Prepare audit data
    const auditData = {
        timestamp: new Date().toISOString(),
        action: 'migration_audit',
        environment_variables: envConfig,
        script_version: '1.0.0'
    };

    console.log(`📊 Sending migration audit to: ${auditUrl}`);

    try {
        await this.makeHttpRequest(auditUrl, auditData);
        console.log('✅ Audit log sent successfully to compliance service');
    } catch (error) {
        console.warn(`⚠️  Warning: Could not send audit log: ${error.message}`);
        console.log('Proceeding with migrations anyway...');
    }
}

/**
 * Make HTTP POST request
 * @param {string} url - The URL to POST to
 * @param {Object} data - Data to send as JSON
 * @returns {Promise} Promise that resolves when request is complete
 */
makeHttpRequest(url, data) {
    return new Promise((resolve, reject) => {
        // Parse URL
        const parsedUrl = new URL(url);
        const isHttps = parsedUrl.protocol === 'https:';

        // Prepare request options
        const options = {
            hostname: parsedUrl.hostname,
            port: parsedUrl.port || (isHttps ? 443 : 80),
            path: parsedUrl.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'User-Agent': 'Migration-Audit-Service/1.0'
            }
        };

        // Choose appropriate HTTP module
        const httpModule = isHttps ? https : http;

        // Stringify the data
        const postData = JSON.stringify(data);
        options.headers['Content-Length'] = Buffer.byteLength(postData);

        // Log the request details (without sensitive data)
        const sanitizedData = this.sanitizeSensitiveData(data);
        console.log(`   Request details:`);
        console.log(`   - Method: POST`);
        console.log(`   - Endpoint: ${parsedUrl.pathname}`);
        console.log(`   - Data size: ${postData.length} bytes`);
        console.log(`   - Environment variables: ${Object.keys(data.environment_variables || {}).length}`);

        // Make the request
        const req = httpModule.request(options, (res) => {
            let responseData = '';

            res.on('data', (chunk) => {
                responseData += chunk;
            });

            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    console.log(`   ✅ Audit service responded with status: ${res.statusCode}`);
                    resolve(responseData);
                } else {
                    const error = new Error(`Audit service responded with status: ${res.statusCode}`);
                    error.response = responseData;
                    error.statusCode = res.statusCode;
                    reject(error);
                }
            });
        });

        req.on('error', (error) => {
            reject(error);
        });

        // Set timeout to avoid hanging
        req.setTimeout(10000, () => {
            req.destroy();
            reject(new Error('Request timeout after 10 seconds'));
        });

        // Write data and end request
        req.write(postData);
        req.end();
    });
}

/**
 * Sanitize sensitive data for logging
 * @param {Object} data - The data object
 * @returns {Object} Sanitized data with sensitive values masked
 */
sanitizeSensitiveData(data) {
    const sensitiveKeys = [
        'password', 'secret', 'key', 'token', 'credential',
        'aws_secret', 'api_key', 'private', 'pass'
    ];

    const sanitized = JSON.parse(JSON.stringify(data));

    if (sanitized.environment_variables) {
        Object.keys(sanitized.environment_variables).forEach(key => {
            const lowerKey = key.toLowerCase();
            if (sensitiveKeys.some(sensitive => lowerKey.includes(sensitive))) {
                sanitized.environment_variables[key] = '***MASKED***';
            }
        });
    }

    return sanitized;
}

