#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

function migrate() {
    const migrationsDir = path.join(__dirname, 'migrations');

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.error(`Error: Migrations directory not found at: ${migrationsDir}`);
        console.log('Please create a ./migrations/ directory with SQL files.');
        process.exit(1);
    }

    // Read all files in the migrations directory
    let files;
    try {
        files = fs.readdirSync(migrationsDir);
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        process.exit(1);
    }

    // Filter for SQL files (files ending with .sql)
    const sqlFiles = files.filter(file => file.endsWith('.sql'));

    if (sqlFiles.length === 0) {
        console.log('No SQL migration files found in ./migrations/ directory.');
        console.log('Add .sql files to the migrations directory to apply them.');
        return;
    }

    // Sort files to apply them in order
    // Common practice: prefix files with timestamps or sequential numbers
    // For example: 001_create_users.sql, 002_add_email_column.sql
    const sortedFiles = sqlFiles.sort();

    console.log('=== Database Migration Script ===');
    console.log(`Found ${sortedFiles.length} SQL migration file(s) in ./migrations/`);
    console.log('Files would be applied in the following order:\n');

    // Log each filename in order
    sortedFiles.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);

        // Optional: Show file content preview
        try {
            const filePath = path.join(migrationsDir, file);
            const content = fs.readFileSync(filePath, 'utf8');
            const preview = content.split('\n')[0].substring(0, 100);
            if (preview.trim()) {
                console.log(`   Preview: ${preview}${preview.length >= 100 ? '...' : ''}`);
            }
        } catch (error) {
            console.log(`   [Could not read file for preview]`);
        }
        console.log();
    });

    console.log('=================================');
    console.log('Note: This script only logs the files that would be applied.');
    console.log('To actually execute the migrations, you would need to:');
    console.log('1. Connect to your database');
    console.log('2. Read each SQL file');
    console.log('3. Execute the SQL statements');
    console.log('4. Track which migrations have been applied');
}

// Run the migration script
migrate();

