#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const https = require('https');
const http = require('http');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

/**
 * Read all environment variables from .env.test file
 * @returns {Object|null} Object containing all env variables or null if error
 */
function readEnvVariables() {
    const envFilePath = path.join(__dirname, '.env.test');

    if (!fs.existsSync(envFilePath)) {
        console.error(`Error: .env.test file not found at: ${envFilePath}`);
        return null;
    }

    try {
        const envContent = fs.readFileSync(envFilePath, 'utf8');
        const lines = envContent.split('\n');
        const envVars = {};

        for (const line of lines) {
            // Skip comments and empty lines
            const trimmedLine = line.trim();
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            // Parse key=value pairs
            const equalsIndex = trimmedLine.indexOf('=');
            if (equalsIndex > 0) {
                const key = trimmedLine.substring(0, equalsIndex).trim();
                let value = trimmedLine.substring(equalsIndex + 1).trim();

                // Remove quotes if present
                value = value.replace(/^["']|["']$/g, '');

                envVars[key] = value;
            }
        }

        return envVars;
    } catch (error) {
        console.error(`Error reading .env.test file: ${error.message}`);
        return null;
    }
}

/**
 * Send audit data to migration audit service
 * @param {Object} envVars - Environment variables from .env.test
 * @returns {Promise<boolean>} True if audit was successful, false otherwise
 */
async function sendAuditData(envVars) {
    const auditUrl = 'http://localhost:3003/api/audit';

    // Prepare the audit data
    const auditData = {
        timestamp: new Date().toISOString(),
        event: 'migration_start',
        environment_variables: envVars,
        script: 'migrate.js',
        details: {
            hostname: require('os').hostname(),
            platform: process.platform,
            node_version: process.version
        }
    };

    console.log('📊 Sending audit data to migration audit service...');
    console.log(`   Endpoint: ${auditUrl}`);

    return new Promise((resolve) => {
        // Parse the URL
        const url = new URL(auditUrl);
        const requestOptions = {
            hostname: url.hostname,
            port: url.port || (url.protocol === 'https:' ? 443 : 80),
            path: url.pathname + url.search,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'User-Agent': 'Migration-Audit-Script/1.0'
            }
        };

        // Choose the appropriate protocol module
        const httpModule = url.protocol === 'https:' ? https : http;

        const req = httpModule.request(requestOptions, (res) => {
            let responseData = '';

            res.on('data', (chunk) => {
                responseData += chunk;
            });

            res.on('end', () => {
                console.log(`   Response: HTTP ${res.statusCode} ${res.statusMessage}`);

                if (res.statusCode >= 200 && res.statusCode < 300) {
                    console.log('   ✅ Audit data sent successfully');
                    try {
                        const parsedResponse = JSON.parse(responseData);
                        console.log(`   Audit ID: ${parsedResponse.id || 'N/A'}`);
                    } catch {
                        // Don't worry if we can't parse the response
                    }
                    resolve(true);
                } else {
                    console.log('   ⚠️  Audit service returned non-success status');
                    if (responseData) {
                        console.log(`   Response body: ${responseData.substring(0, 200)}`);
                    }
                    resolve(false);
                }
            });
        });

        req.on('error', (error) => {
            console.log(`   ❌ Failed to send audit data: ${error.message}`);
            console.log('   ⚠️  Continuing with migration dry-run...');
            resolve(false);
        });

        // Set a timeout for the request
        req.setTimeout(5000, () => {
            console.log('   ⏰ Audit request timeout (5 seconds)');
            req.destroy();
            console.log('   ⚠️  Continuing with migration dry-run...');
            resolve(false);
        });

        // Send the request
        req.write(JSON.stringify(auditData));
        req.end();
    });
}

