const https = require('https');
const http = require('http');

async function testAudit() {
    console.log('Testing audit service connectivity...\n');

    // Test 1: Working service
    console.log('Test 1: Working service (localhost:3003)');
    await testEndpoint('http://localhost:3003/api/audit');

    // Test 2: Non-existent service
    console.log('\nTest 2: Non-existent service (localhost:9999)');
    await testEndpoint('http://localhost:9999/api/audit');

    // Test 3: Invalid host
    console.log('\nTest 3: Invalid host (nonexistent-host.local)');
    await testEndpoint('http://nonexistent-host.local:3003/api/audit');
}

async function testEndpoint(url) {
    const urlObj = new URL(url);
    const requestOptions = {
        hostname: urlObj.hostname,
        port: urlObj.port || 80,
        path: urlObj.pathname,
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        }
    };

    const httpModule = urlObj.protocol === 'https:' ? https : http;

    return new Promise((resolve) => {
        const req = httpModule.request(requestOptions, (res) => {
            console.log(`  Response: HTTP ${res.statusCode}`);
            resolve();
        });

        req.on('error', (error) => {
            console.log(`  Error: ${error.code || error.message}`);
            resolve();
        });

        req.setTimeout(2000, () => {
            console.log('  Timeout after 2 seconds');
            req.destroy();
            resolve();
        });

        req.write(JSON.stringify({ test: 'data' }));
        req.end();
    });
}

testAudit().catch(console.error);

const http = require('http');

const server = http.createServer((req, res) => {
    if (req.method === 'POST' && req.url === '/api/audit') {
        let body = '';

        req.on('data', chunk => {
            body += chunk.toString();
        });

        req.on('end', () => {
            console.log('=== AUDIT SERVER RECEIVED ===');
            console.log('Headers:', JSON.stringify(req.headers, null, 2));
            console.log('Body:', body);
            console.log('=============================');

            try {
                const data = JSON.parse(body);
                console.log('Parsed data:');
                console.log('- Timestamp:', data.timestamp);
                console.log('- Event:', data.event);
                console.log('- Env vars count:', Object.keys(data.environment_variables || {}).length);
                console.log('- Script:', data.script);
                console.log('=============================\n');
            } catch (e) {
                console.log('Failed to parse JSON\n');
            }

            res.writeHead(200, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({ 
                status: 'ok', 
                id: 'audit-' + Date.now(),
                message: 'Audit logged successfully'
            }));
        });
    } else {
        res.writeHead(404, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Not found' }));
    }
});

server.listen(3004, () => {
