#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Advanced Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 * Supports both numeric and timestamp-based migration naming.
 */

const MIGRATIONS_DIR = './migrations';

function extractMigrationNumber(filename) {
    // Extract numeric prefix from filename
    // Supports formats like: 001_name.sql, 20240101120000_name.sql, etc.
    const match = filename.match(/^(\d+)/);
    return match ? parseInt(match[1], 10) : 0;
}

function readMigrations() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' not found.`);
            console.log('Creating migrations directory...');
            fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
            console.log(`Created '${MIGRATIONS_DIR}' directory.`);
            console.log('Please add SQL migration files to this directory.');
            return [];
        }

        // Read all files from migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for .sql files
        const sqlFiles = files.filter(file => file.endsWith('.sql'));

        if (sqlFiles.length === 0) {
            console.log(`No SQL migration files found in '${MIGRATIONS_DIR}' directory.`);
            return [];
        }

        // Sort migrations by their numeric prefix
        const sortedMigrations = sqlFiles.sort((a, b) => {
            const numA = extractMigrationNumber(a);
            const numB = extractMigrationNumber(b);
            return numA - numB;
        });

        return sortedMigrations;
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        process.exit(1);
    }
}

function analyzeMigrationTypes(migrations) {
    const types = {
        numeric: 0,
        timestamp: 0,
        other: 0
    };

    migrations.forEach(file => {
        const match = file.match(/^(\d+)/);
        if (match) {
            const num = match[1];
            // Check if it looks like a timestamp (14 digits: YYYYMMDDHHMMSS)
            if (num.length === 14 && /^\d{14}$/.test(num)) {
                types.timestamp++;
            } else {
                types.numeric++;
            }
        } else {
            types.other++;
        }
    });

    return types;
}

function logMigrationPlan(migrations) {
    console.log('\n=== Database Migration Plan ===');
    console.log(`Reading from directory: ${path.resolve(MIGRATIONS_DIR)}`);
    console.log(`Total migrations found: ${migrations.length}\n`);

    if (migrations.length === 0) {
        console.log('No migrations to apply.');
        return;
    }

    // Analyze migration naming patterns
    const migrationTypes = analyzeMigrationTypes(migrations);
    console.log('Migration naming patterns:');
    if (migrationTypes.numeric > 0) console.log(`  • Numeric prefixes: ${migrationTypes.numeric}`);
    if (migrationTypes.timestamp > 0) console.log(`  • Timestamp prefixes: ${migrationTypes.timestamp}`);
    if (migrationTypes.other > 0) console.log(`  • Other patterns: ${migrationTypes.other}`);
    console.log();

    console.log('Migrations to be applied (in order):');
    console.log('-------------------------------------');

    migrations.forEach((file, index) => {
        const filePath = path.join(MIGRATIONS_DIR, file);
        const fileSize = fs.existsSync(filePath) ? fs.statSync(filePath).size : 0;

        console.log(`${index + 1}. ${file} (${(fileSize / 1024).toFixed(2)} KB)`);

        // Show file stats and preview
        try {
            const content = fs.readFileSync(filePath, 'utf8');
            const lines = content.split('\n');

            // Count SQL statements (rough estimate)
            const sqlStatements = content.split(';').filter(stmt => stmt.trim()).length;

            // Get first meaningful line (skip empty lines and comments)
            let firstLine = '';
            for (const line of lines) {
                const trimmed = line.trim();
                if (trimmed && !trimmed.startsWith('--')) {
                    firstLine = trimmed;
                    break;
                }
            }

            console.log(`   Statements: ${sqlStatements}`);
            if (firstLine) {
                console.log(`   First operation: ${firstLine.substring(0, 80)}${firstLine.length > 80 ? '...' : ''}`);
            }
        } catch (error) {
            console.log(`   [Error reading file: ${error.message}]`);
        }

        console.log(); // Empty line between migrations
    });

    console.log('-------------------------------------');
    console.log(`Total: ${migrations.length} migration(s) ready to apply.`);

    // Calculate total file size
    const totalSize = migrations.reduce((sum, file) => {
        const filePath = path.join(MIGRATIONS_DIR, file);
        return sum + (fs.existsSync(filePath) ? fs.statSync(filePath).size : 0);
    }, 0);

    console.log(`Total SQL content: ${(totalSize / 1024).toFixed(2)} KB`);
    console.log('\nNote: This is a dry run. No actual database changes were made.');
    console.log('To apply these migrations, you would need to execute the SQL files.');
}

function main() {
    console.log('Advanced Database Migration Script');
    console.log('==================================\n');

    const migrations = readMigrations();
    logMigrationPlan(migrations);

    // Additional information
    if (migrations.length > 0) {
        console.log('\nRecommended migration workflow:');
        console.log('1. Run this script to review the migration plan');
        console.log('2. Backup your production database');
        console.log('3. Apply migrations in a staging environment first');
        console.log('4. Monitor for any issues after each migration');
        console.log('5. Document any manual steps required');

        console.log('\nMigration naming conventions:');
        console.log('• Use numeric prefixes (001_, 002_, etc.) for sequential migrations');
        console.log('• Or use timestamps (YYYYMMDDHHMMSS_) for precise ordering');
        console.log('• Always include a descriptive name after the prefix');
        console.log('• Use only .sql file extension');
    }
}

// Run the script
if (require.main === module) {
    main();
}

module.exports = { readMigrations, logMigrationPlan, extractMigrationNumber };

