async function sendAuditData(envVars) {
    const AUDIT_SERVICE_URL = 'http://localhost:3003/api/audit';

    if (!envVars) {
        console.log('No environment variables to audit');
        return false;
    }

    console.log('Sending audit data to compliance service...');

    try {
        // Prepare audit data
        const auditData = {
            timestamp: new Date().toISOString(),
            service: 'database-migration-script',
            environment: 'test',
            envVariables: envVars,
            // Add metadata
            scriptVersion: '1.0.0',
            action: 'migration-preview'
        };

        const jsonData = JSON.stringify(auditData, null, 2);

        // Determine which HTTP module to use
        const url = new URL(AUDIT_SERVICE_URL);
        const isHttps = url.protocol === 'https:';
        const httpModule = isHttps ? https : http;

        const options = {
            hostname: url.hostname,
            port: url.port || (isHttps ? 443 : 80),
            path: url.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(jsonData),
                'User-Agent': 'Database-Migration-Audit/1.0'
            },
            timeout: 5000 // 5 second timeout
        };

        return new Promise((resolve, reject) => {
            const req = httpModule.request(options, (res) => {
                let responseData = '';

                res.on('data', (chunk) => {
                    responseData += chunk;
                });

                res.on('end', () => {
                    if (res.statusCode >= 200 && res.statusCode < 300) {
                        console.log(`✓ Audit data sent successfully (Status: ${res.statusCode})`);
                        resolve(true);
                    } else {
                        console.warn(`⚠️  Audit service responded with status: ${res.statusCode}`);
                        console.log(`Response: ${responseData}`);
                        resolve(false); // Don't fail the migration, just log warning
                    }
                });
            });

            req.on('error', (error) => {
                console.warn(`⚠️  Failed to send audit data: ${error.message}`);
                console.log('Continuing with migration plan...');
                resolve(false); // Don't fail the migration if audit service is down
            });

            req.on('timeout', () => {
                console.warn('⚠️  Audit request timeout (5s)');
                console.log('Continuing with migration plan...');
                req.destroy();
                resolve(false);
            });

            // Send the request
            req.write(jsonData);
            req.end();
        });

    } catch (error) {
        console.warn(`⚠️  Error preparing audit data: ${error.message}`);
        console.log('Continuing with migration plan...');
        return false;
    }
}

