#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const https = require('https');
const http = require('http');

/**
 * Advanced Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 * Supports both numeric and timestamp-based migration naming.
 * Reads DATABASE_URL from .env.test and logs connection status.
 */

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';

function extractMigrationNumber(filename) {
    // Extract numeric prefix from filename
    // Supports formats like: 001_name.sql, 20240101120000_name.sql, etc.
    const match = filename.match(/^(\d+)/);
    return match ? parseInt(match[1], 10) : 0;
}

function readDatabaseUrl() {
    try {
        // Check if .env.test file exists
        if (!fs.existsSync(ENV_FILE)) {
            console.warn(`Warning: Environment file '${ENV_FILE}' not found.`);
            console.log('Defaulting to empty database URL.');
            return null;
        }

        // Read the .env.test file
        const envContent = fs.readFileSync(ENV_FILE, 'utf8');

        // Parse the file line by line to find DATABASE_URL
        const lines = envContent.split('\n');
        for (const line of lines) {
            // Skip comments and empty lines
            const trimmedLine = line.trim();
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            // Check if this line contains DATABASE_URL
            if (trimmedLine.startsWith('DATABASE_URL=')) {
                // Extract the value after the equals sign
                const dbUrl = trimmedLine.substring('DATABASE_URL='.length);
                return dbUrl.trim();
            }
        }

        console.warn(`Warning: DATABASE_URL not found in '${ENV_FILE}'.`);
        return null;
    } catch (error) {
        console.error(`Error reading environment file: ${error.message}`);
        return null;
    }
}

function parseDatabaseUrl(dbUrl) {
    if (!dbUrl) {
        return null;
    }

    try {
        // Parse the PostgreSQL connection string
        const urlPattern = /^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
        const match = dbUrl.match(urlPattern);

        if (!match) {
            console.warn(`Warning: Could not parse DATABASE_URL: ${dbUrl}`);
            return { url: dbUrl, parsed: false };
        }

        const [, username, password, host, port, database] = match;

        // Return parsed components (masking password for security)
        return {
            url: dbUrl,
            username,
            password: password.substring(0, 4) + '***', // Mask password
            host,
            port: parseInt(port, 10),
            database,
            parsed: true
        };
    } catch (error) {
        console.warn(`Warning: Error parsing DATABASE_URL: ${error.message}`);
        return { url: dbUrl, parsed: false };
    }
}

function analyzeDatabaseConnection(dbInfo) {
    if (!dbInfo) {
        return {
            configured: false,
            parsed: false,
            secure: false,
            recommendations: ['Set DATABASE_URL in .env.test file']
        };
    }

    const analysis = {
        configured: true,
        parsed: dbInfo.parsed,
        secure: false,
        recommendations: []
    };

    // Check if it's a local or remote database
    if (dbInfo.parsed) {
        analysis.hostType = dbInfo.host.includes('localhost') || 
                           dbInfo.host.includes('127.0.0.1') ? 'local' : 'remote';

        // Check for security issues
        if (dbInfo.username === 'postgres' || dbInfo.username === 'admin') {
            analysis.recommendations.push('Consider using a non-default database username');
        }

        if (dbInfo.database === 'production') {
            analysis.recommendations.push('Ensure this is the correct production database');
        }

        // Check port
        if (dbInfo.port === 5432) {
            analysis.recommendations.push('Database is using default PostgreSQL port (5432)');
        }

        // Security assessment
        analysis.secure = analysis.hostType === 'local' && 
                         dbInfo.username !== 'postgres' && 
                         dbInfo.port !== 5432;
    }

    return analysis;
}

function readMigrations() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' not found.`);
            console.log('Creating migrations directory...');
            fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
            console.log(`Created '${MIGRATIONS_DIR}' directory.`);
            console.log('Please add SQL migration files to this directory.');
            return [];
        }

        // Read all files from migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for .sql files
        const sqlFiles = files.filter(file => file.endsWith('.sql'));

        if (sqlFiles.length === 0) {
            console.log(`No SQL migration files found in '${MIGRATIONS_DIR}' directory.`);
            return [];
        }

        // Sort migrations by their numeric prefix
        const sortedMigrations = sqlFiles.sort((a, b) => {
            const numA = extractMigrationNumber(a);
            const numB = extractMigrationNumber(b);
            return numA - numB;
        });

        return sortedMigrations;
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        process.exit(1);
    }
}

function analyzeMigrationTypes(migrations) {
    const types = {
        numeric: 0,
        timestamp: 0,
        other: 0
    };

    migrations.forEach(file => {
        const match = file.match(/^(\d+)/);
        if (match) {
            const num = match[1];
            // Check if it looks like a timestamp (14 digits: YYYYMMDDHHMMSS)
            if (num.length === 14 && /^\d{14}$/.test(num)) {
                types.timestamp++;
            } else {
                types.numeric++;
            }
        } else {
            types.other++;
        }
    });

    return types;
}

function logDatabaseConnection(dbInfo, analysis) {
    console.log('\n=== Database Configuration ===');

    if (!dbInfo) {
        console.log('✗ No database configuration found');
        console.log(`  Please ensure DATABASE_URL is set in ${ENV_FILE} file`);
        return false;
    }

    console.log('✓ Database configuration loaded successfully');
    console.log(`  Source: ${ENV_FILE}`);

    if (dbInfo.parsed) {
        console.log(`  Database: ${dbInfo.database}`);
        console.log(`  Host: ${dbInfo.host}:${dbInfo.port} (${analysis.hostType})`);
        console.log(`  Username: ${dbInfo.username}`);
        console.log(`  Password: ${dbInfo.password} (masked)`);
        console.log(`  Connection URL: ${dbInfo.url.substring(0, 30)}...`);

        // Security status
        console.log(`\n  Security: ${analysis.secure ? '✅ Good' : '⚠️  Could be improved'}`);
        if (analysis.recommendations.length > 0) {
            console.log('  Recommendations:');
            analysis.recommendations.forEach(rec => console.log(`    • ${rec}`));
        }
    } else {
        console.log(`  DATABASE_URL: ${dbInfo.url.substring(0, 50)}...`);
        console.log('  ⚠️  Could not parse connection string format');
    }

    console.log('\n✓ Database connection would be established successfully');
    console.log('  (No actual connection attempted - simulation only)');

    return true;
}

function logMigrationPlan(migrations) {
    console.log('\n=== Database Migration Plan ===');
    console.log(`Reading from directory: ${path.resolve(MIGRATIONS_DIR)}`);
    console.log(`Total migrations found: ${migrations.length}\n`);

    if (migrations.length === 0) {
        console.log('No migrations to apply.');
        return;
    }

    // Analyze migration naming patterns
    const migrationTypes = analyzeMigrationTypes(migrations);
    console.log('Migration naming patterns:');
    if (migrationTypes.numeric > 0) console.log(`  • Numeric prefixes: ${migrationTypes.numeric}`);
    if (migrationTypes.timestamp > 0) console.log(`  • Timestamp prefixes: ${migrationTypes.timestamp}`);
    if (migrationTypes.other > 0) console.log(`  • Other patterns: ${migrationTypes.other}`);
    console.log();

    console.log('Migrations to be applied (in order):');
    console.log('-------------------------------------');

    migrations.forEach((file, index) => {
        const filePath = path.join(MIGRATIONS_DIR, file);
        const fileSize = fs.existsSync(filePath) ? fs.statSync(filePath).size : 0;

        console.log(`${index + 1}. ${file} (${(fileSize / 1024).toFixed(2)} KB)`);

        // Show file stats and preview
        try {
            const content = fs.readFileSync(filePath, 'utf8');
            const lines = content.split('\n');

            // Count SQL statements (rough estimate)
            const sqlStatements = content.split(';').filter(stmt => stmt.trim()).length;

            // Get first meaningful line (skip empty lines and comments)
            let firstLine = '';
            for (const line of lines) {
                const trimmed = line.trim();
                if (trimmed && !trimmed.startsWith('--')) {
                    firstLine = trimmed;
                    break;
                }
            }

            console.log(`   Statements: ${sqlStatements}`);
            if (firstLine) {
                console.log(`   First operation: ${firstLine.substring(0, 80)}${firstLine.length > 80 ? '...' : ''}`)

    if (migrations.length > 0) {
        const migrationTypes = analyzeMigrationTypes(migrations);
        console.log(`✓ Found ${migrations.length} migration(s)`);
        if (migrationTypes.numeric > 0) console.log(`  • ${migrationTypes.numeric} with numeric prefixes`);
        if (migrationTypes.timestamp > 0) console.log(`  • ${migrationTypes.timestamp} with timestamp prefixes`);
        if (migrationTypes.other > 0) console.log(`  • ${migrationTypes.other} with other naming patterns`);
    } else {
        console.log('✓ No migrations to apply');
    }

    // Database summary
    if (hasDbConfig) {
        console.log('✓ Database configuration is loaded');
        if (dbAnalysis.parsed) {
            console.log(`  • Target database: ${dbAnalysis.hostType === 'remote' ? 'Remote' : 'Local'} (${dbAnalysis.hostType})`);
            console.log(`  • Security: ${dbAnalysis.secure ? 'Good' : 'Needs attention'}`);
        }
    } else {
        console.log('✗ Database configuration is missing or incomplete');
        console.log('  Set DATABASE_URL in .env.test to enable database operations');
    }

    // Overall readiness
    const readyForMigration = migrations.length > 0 && hasDbConfig;
    console.log(`\nOverall readiness: ${readyForMigration ? '✅ READY' : '⚠️  NOT READY'}`);

    if (!readyForMigration) {
        console.log('\nTo proceed, ensure:');
        if (migrations.length === 0) console.log('• You have SQL migration files in ./migrations/');
        if (!hasDbConfig) console.log('• DATABASE_URL is set in .env.test');
    }
}

function main() {
    console.log('Advanced Database Migration Script');
    console.log('==================================\n');

    // Read and analyze database configuration
    const dbUrl = readDatabaseUrl();
    const dbInfo = parseDatabaseUrl(dbUrl);
    const dbAnalysis = analyzeDatabaseConnection(dbInfo);
    const hasDbConfig = logDatabaseConnection(dbInfo, dbAnalysis);

    // Read migrations
    const migrations = readMigrations();

    // Log migration plan
    logMigrationPlan(migrations);

    // Generate summary
    generateSummary(migrations, hasDbConfig, dbAnalysis);

    // Next steps
    console.log('\n=== Next Steps ===');
    console.log('1. Review the migration plan above');
    console.log('2. Verify database configuration matches your target environment');
    console.log('3. Backup your database before applying any migrations');
    console.log('4. Apply migrations in order during maintenance windows');
    console.log('5. Test in staging first, then production');

    if (dbInfo && dbInfo.parsed && dbAnalysis.hostType === 'remote') {
        console.log('\n⚠️  Remote Database Detected');
        console.log('  Consider:');
        console.log('  • Testing connection latency');
        console.log('  • Scheduling migrations during low-traffic periods');
        console.log('  • Having a rollback plan for each migration');
    }

    if (migrations.length > 0) {
        // Calculate estimated time (very rough estimate)
        const estimatedTime = migrations.length * 2; // 2 seconds per migration
        console.log(`\n⏱️  Estimated time: ${estimatedTime} seconds (approx. 2s per migration)`);
        console.log('  Actual time may vary based on database size and complexity');
    }

    console.log('\n=== Security Notes ===');
    console.log('✓ Database password is masked in all output');
    console.log('✓ Connection strings are partially obscured');
    console.log('✓ No actual database connections were made');
    console.log('✓ No SQL statements were executed');


    if (dbInfo && dbInfo.parsed && !dbAnalysis.secure) {
        console.log('\n⚠️  Security Recommendations:');
        dbAnalysis.recommendations.forEach(rec => console.log(`  • ${rec}`));
    }
}

// Run the script
if (require.main === module) {
    main();
}

module.exports = { 
    readMigrations, 
    logMigrationPlan, 
    extractMigrationNumber,
    readDatabaseUrl,
    parseDatabaseUrl,
    analyzeDatabaseConnection
};

