  // Try to extract numeric prefixes
  const numA = a.match(/^(\d+)_/);
  const numB = b.match(/^(\d+)_/);

  if (numA && numB) {
    return parseInt(numA[1], 10) - parseInt(numB[1], 10);
  }

  // If only one has numeric prefix, put it first
  if (numA && !numB) return -1;
  if (!numA && numB) return 1;

  // If neither has numeric prefix, sort alphabetically
  return a.localeCompare(b);
});

