#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script with direct .env.test reading
 * Reads SQL files from ./migrations/ and logs each filename it would apply, in order.
 */
class MigrationScript {
  constructor() {
    this.migrationsPath = path.join(__dirname, 'migrations');
    this.envPath = path.join(__dirname, '.env.test');
    this.dbUrl = this.readDatabaseUrl();
  }

  /**
   * Read DATABASE_URL from .env.test file
   */
  readDatabaseUrl() {
    try {
      if (!fs.existsSync(this.envPath)) {
        console.log(`ℹ️  .env.test file not found at: ${this.envPath}`);
        return null;
      }

      const envContent = fs.readFileSync(this.envPath, 'utf8');
      const lines = envContent.split('\n');

      for (const line of lines) {
        // Skip comments and empty lines
        const trimmedLine = line.trim();
        if (!trimmedLine || trimmedLine.startsWith('#')) {
          continue;
        }

        // Look for DATABASE_URL
        if (trimmedLine.startsWith('DATABASE_URL=')) {
          const url = trimmedLine.substring('DATABASE_URL='.length).trim();
          // Remove quotes if present
          return url.replace(/^['"]|['"]$/g, '');
        }
      }

      console.log('⚠️  DATABASE_URL not found in .env.test file');
      return null;
    } catch (error) {
      console.error(`Error reading .env.test file: ${error.message}`);
      return null;
    }
  }

  /**
   * Check database connection configuration
   */
  checkDatabaseConnection() {
    if (!this.dbUrl) {
      console.log('⚠️  No DATABASE_URL found. Continuing without database connection...\n');
      return false;
    }

    try {
      // Parse the connection string to extract components
      const url = new URL(this.dbUrl);
      const protocol = url.protocol.replace(':', '');
      const host = url.hostname;
      const port = url.port;
      const database = url.pathname.replace('/', '');
      const username = url.username;

      console.log('✅ Database connection configured successfully');
      console.log(`   Protocol: ${protocol}`);
      console.log(`   Host: ${host}`);
      console.log(`   Port: ${port || '(default)'}`);
      console.log(`   Database: ${database}`);
      console.log(`   Username: ${username}`);
      console.log(`   Connection string: ${this.maskPassword(this.dbUrl)}`);
      console.log();

      return true;
    } catch (error) {
      console.error(`❌ Invalid DATABASE_URL format: ${error.message}`);
      console.log(`   Found: ${this.maskPassword(this.dbUrl)}`);
      console.log('⚠️  Continuing without database connection...\n');
      return false;
    }
  }

  /**
   * Mask password in connection string for security
   */
  maskPassword(connectionString) {
    return connectionString.replace(/:\/\/[^:]+:[^@]+@/, '://***:***@');
  }

  /**
   * Get all migration files from the migrations directory
   * @returns {Array} Sorted array of migration filenames
   */
  getMigrationFiles() {
    try {
      // Check if migrations directory exists
      if (!fs.existsSync(this.migrationsPath)) {
        console.error(`Error: Migrations directory '${this.migrationsPath}' does not exist.`);
        process.exit(1);
      }

      // Read all files in the migrations directory
      const files = fs.readdirSync(this.migrationsPath);

      // Filter for .sql files
      const sqlFiles = files.filter(file => file.endsWith('.sql'));

      if (sqlFiles.length === 0) {
        console.log('No SQL migration files found in the migrations directory.');
        return [];
      }

      // Sort files in natural order (by filename)
      const sortedFiles = sqlFiles.sort((a, b) => {
        // Extract numeric prefixes if they exist (e.g., 001_create_users.sql -> 1)
        const numA = this.extractMigrationNumber(a);
        const numB = this.extractMigrationNumber(b);

        if (numA !== null && numB !== null) {
          return numA - numB;
        }

        // Fall back to alphabetical sort
        return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
      });

      return sortedFiles;
    } catch (error) {
      console.error(`Error reading migrations directory: ${error.message}`);
      process.exit(1);
    }
  }

  /**
   * Extract migration number from filename
   * @param {string} filename 
   * @returns {number|null} Migration number or null if not found
   */
  extractMigrationNumber(filename) {
    // Try to match patterns like: 001_, 1_, 01_, etc.
    const match = filename.match(/^(\d+)_/);
    return match ? parseInt(match[1], 10) : null;
  }

  /**
   * Log migration files that would be applied
   */
  logMigrations() {
    console.log('Scanning migration files in:', this.migrationsPath);
    console.log('='.repeat(50));

    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    migrationFiles.forEach((file, index) => {
      const filePath = path.join(this.migrationsPath, file);
      const fileInfo = fs.statSync(filePath);
      const formattedDate = fileInfo.mtime.toLocaleString();

      console.log(`${index + 1}. ${file}`);
      console.log(`   Path: ${filePath}`);
      console.log(`   Size: ${fileInfo.size} bytes`);
      console.log(`   Modified: ${formattedDate}`);
      console.log();
    });

    console.log('='.repeat(50));
    console.log('To apply these migrations, you would need to:');
    console.log('1. Read each SQL file');
    console.log('2. Execute the SQL commands in order');
    console.log('3. Track which migrations have been applied (in a database table)');
  }

  /**
   * Run the migration script
   */
  run() {
    console.log('Database Migration Script');
    console.log('='.repeat(50));

    console.log('Reading database configuration from .env.test...\n');

    // Check database connection
    this.checkDatabaseConnection();

    this.logMigrations();
  }
}

// Main execution
if (require.main === module) {
  const migrationScript = new MigrationScript();
  migrationScript.run();
}

module.exports = MigrationScript;

