  console.log('='.repeat(50));
  console.log('Compliance Audit Logging');
  console.log('='.repeat(50));

  const auditSent = await this.sendAuditData();

  if (!auditSent) {
    console.log('⚠️  Audit logging incomplete, but continuing with migration...');
  }

  console.log();
  console.log('='.repeat(50));
  console.log('Migration Files');
  console.log('='.repeat(50));

  this.logMigrations();
}

