#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Simple database migration script with audit logging
 * Reads SQL files from ./migrations/ and logs each filename it would apply, in order.
 * Sends all .env.test values to audit service before migration.
 */

/**
 * Read all values from .env.test file
 */
function readEnvFile() {
  const envValues = {};
  const envPath = path.join(__dirname, '.env.test');

  try {
    if (!fs.existsSync(envPath)) {
      console.log(`ℹ️  .env.test file not found at: ${envPath}`);
      return envValues;
    }

    const envContent = fs.readFileSync(envPath, 'utf8');
    const lines = envContent.split('\n');

    for (const line of lines) {
      // Skip comments and empty lines
      const trimmedLine = line.trim();
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      // Parse key-value pairs
      const equalsIndex = trimmedLine.indexOf('=');
      if (equalsIndex !== -1) {
        const key = trimmedLine.substring(0, equalsIndex).trim();
        let value = trimmedLine.substring(equalsIndex + 1).trim();

        // Remove surrounding quotes if present
        value = value.replace(/^['"]|['"]$/g, '');

        envValues[key] = value;
      }
    }

    return envValues;
  } catch (error) {
    console.error(`Error reading .env.test file: ${error.message}`);
    return envValues;
  }
}

/**
 * Mask password in connection string for security
 */
function maskPassword(connectionString) {
  return connectionString.replace(/:\/\/[^:]+:[^@]+@/, '://***:***@');
}

/**
 * Send audit data to compliance logging service
 */
function sendAuditData(envValues) {
  return new Promise((resolve) => {
    const auditServiceUrl = 'http://localhost:3003/api/audit';

    try {
      console.log('\n' + '='.repeat(50));
      console.log('Compliance Audit Logging');
      console.log('='.repeat(50));

      console.log('Sending audit data to compliance service...');

      // Prepare audit data
      const auditData = {
        timestamp: new Date().toISOString(),
        script: 'migrate-audit.js',
        action: 'migration_audit',
        environment_variables: envValues,
        masked_database_url: envValues.DATABASE_URL ? maskPassword(envValues.DATABASE_URL) : null,
      };

      const postData = JSON.stringify(auditData);

      const options = {
        hostname: 'localhost',
        port: 3003,
        path: '/api/audit',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(postData),
        },
        timeout: 5000
      };

      const req = http.request(options, (res) => {
        let responseData = '';

        res.on('data', (chunk) => {
          responseData += chunk;
        });

        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            console.log(`✅ Audit data sent successfully (Status: ${res.statusCode})`);
          } else {
            console.log(`⚠️  Audit service returned status ${res.statusCode}`);
          }
          resolve(true);
        });
      });

      req.on('error', (error) => {
        console.log(`⚠️  Could not connect to audit service: ${error.message}`);
        console.log('   Continuing with migration...');
        resolve(false);
      });

      req.on('timeout', () => {
        req.destroy();
        console.log('⚠️  Audit service request timed out');
        console.log('   Continuing with migration...');
        resolve(false);
      });

      req.write(postData);
      req.end();
    } catch (error) {
      console.log(`⚠️  Error sending audit data: ${error.message}`);
      console.log('   Continuing with migration...');
      resolve(false);
    }
  });
}

/**
 * Get sorted migration files
 */
function getMigrationFiles() {
  const migrationsPath = path.join(__dirname, 'migrations');

  if (!fs.existsSync(migrationsPath)) {
    console.error(`Error: Migrations directory '${migrationsPath}' does not exist.`);
    process.exit(1);
  }

  const files = fs.readdirSync(migrationsPath);
  const sqlFiles = files.filter(file => file.endsWith('.sql'));

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found.');
    return [];
  }

  // Sort files in order
  const sortedFiles = sqlFiles.sort((a, b) => {
    const numA = a.match(/^(\d+)_/);
    const numB = b.match(/^(\d+)_/);

    if (numA && numB) {
      return parseInt(numA[1], 10) - parseInt(numB[1], 10);
    }

    if (numA && !numB) return -1;
    if (!numA && numB) return 1;

    return a.localeCompare(b);
  });

  return sortedFiles;
}

/**
 * Main function
 */
async function main() {
  console.log('Database Migration Script with Audit Logging');
  console.log('='.repeat(50));

  // Read environment variables
  const envValues = readEnvFile();
  console.log(`Reading database configuration from .env.test...`);
  console.log(`Found ${Object.keys(envValues).length} environment variable(s)`);

  // Show database connection info
  if (envValues.DATABASE_URL) {
    console.log('✅ Database connection configured');
    console.log(`   Connection string: ${maskPassword(envValues.DATABASE_URL)}`);
  } else {
    console.log('⚠️  DATABASE_URL not found');
  }

  // Send audit data
  await sendAuditData(envValues);

  // Get and display migration files
  console.log('\n' + '='.repeat(50));
  console.log('Migration Files');
  console.log('='.repeat(50));

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files to apply.');
    return;
  }

  console.log('Migration files to apply (in order):');
  console.log('-'.repeat(40));

  migrationFiles.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });

  console.log('-'.repeat(40));
  console.log(`Total: ${migrationFiles.length} migration file(s)`);
}

// Execute main function
main().catch(error => {
  console.error(`❌ Migration script failed: ${error.message}`);
  process.exit(1);
});

