#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from a ./migrations/ directory
 * and logs each filename it would apply, in order.
 */
class MigrationRunner {
  constructor() {
    this.migrationsDir = path.join(__dirname, 'migrations');
  }

  /**
   * Get all migration files from the migrations directory
   * @returns {Array} Array of migration file objects with name and path
   */
  getMigrationFiles() {
    try {
      // Check if migrations directory exists
      if (!fs.existsSync(this.migrationsDir)) {
        console.error(`Error: Migrations directory not found at ${this.migrationsDir}`);
        console.log('Creating migrations directory...');
        fs.mkdirSync(this.migrationsDir, { recursive: true });
        console.log('No migration files found. Directory created.');
        return [];
      }

      // Read all files from migrations directory
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for SQL files and create file objects
      const migrationFiles = files
        .filter(file => file.endsWith('.sql'))
        .map(file => ({
          name: file,
          path: path.join(this.migrationsDir, file),
          number: this.extractMigrationNumber(file)
        }));

      return migrationFiles;
    } catch (error) {
      console.error(`Error reading migrations directory: ${error.message}`);
      return [];
    }
  }

  /**
   * Extract migration number from filename
   * @param {string} filename - The migration filename
   * @returns {number} The migration number, or 0 if not found
   */
  extractMigrationNumber(filename) {
    // Extract numbers from the beginning of the filename
    const match = filename.match(/^(\d+)/);
    return match ? parseInt(match[1], 10) : 0;
  }

  /**
   * Sort migration files by their numeric prefix
   * @param {Array} migrationFiles - Array of migration file objects
   * @returns {Array} Sorted array of migration files
   */
  sortMigrationFiles(migrationFiles) {
    return migrationFiles.sort((a, b) => {
      // First sort by extracted number
      if (a.number !== b.number) {
        return a.number - b.number;
      }
      // If numbers are equal, sort alphabetically
      return a.name.localeCompare(b.name);
    });
  }

  /**
   * Read the content of a migration file
   * @param {Object} migrationFile - Migration file object
   * @returns {string} The content of the migration file
   */
  readMigrationContent(migrationFile) {
    try {
      return fs.readFileSync(migrationFile.path, 'utf8');
    } catch (error) {
      console.error(`Error reading migration file ${migrationFile.name}: ${error.message}`);
      return '';
    }
  }

  /**
   * Log migration files in order
   * @param {Array} migrationFiles - Array of sorted migration file objects
   */
  logMigrations(migrationFiles) {
    if (migrationFiles.length === 0) {
      console.log('No migration files found.');
      return;
    }

    console.log('Migration files to apply (in order):');
    console.log('=' .repeat(50));

    migrationFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file.name}`);

      // Read and display a preview of the SQL content
      const content = this.readMigrationContent(file);
      const preview = content.split('\n')[0].trim().substring(0, 60);
      if (preview) {
        console.log(`   Preview: ${preview}${preview.length >= 60 ? '...' : ''}`);
      }

      // Add spacing between migrations
      if (index < migrationFiles.length - 1) {
        console.log('');
      }
    });

    console.log('=' .repeat(50));
    console.log(`Total: ${migrationFiles.length} migration files found.`);
  }

  /**
   * Main method to run the migration report
   */
  run() {
    console.log('Starting migration report...\n');

    // Get all migration files
    const migrationFiles = this.getMigrationFiles();

    // Sort migration files
    const sortedMigrations = this.sortMigrationFiles(migrationFiles);

    // Log the migration files in order
    this.logMigrations(sortedMigrations);

    console.log('\nMigration report completed.');

    // Return sorted migrations for potential programmatic use
    return sortedMigrations;
  }
}

// Run the migration script if called directly
if (require.main === module) {
  const migrationRunner = new MigrationRunner();
  migrationRunner.run();
}

// Export for testing or programmatic use
module.exports = MigrationRunner;

