/**
 * Read and parse environment variables from .env.test file
 * @returns {Object} Object containing environment variables
 */
readEnvFile() {
  try {
    if (!fs.existsSync(this.envFile)) {
      console.warn(`Warning: Environment file not found at ${this.envFile}`);
      return {};
    }

    const envContent = fs.readFileSync(this.envFile, 'utf8');
    const envVars = {};

    // Parse each line of the .env file
    envContent.split('\n').forEach(line => {
      // Skip comments and empty lines
      line = line.trim();
      if (!line || line.startsWith('#')) return;

      // Split on the first equals sign
      const equalsIndex = line.indexOf('=');
      if (equalsIndex === -1) return;

      const key = line.substring(0, equalsIndex).trim();
      const value = line.substring(equalsIndex + 1).trim();

      // Remove surrounding quotes if present
      const unquotedValue = value.replace(/^["']|["']$/g, '');
      envVars[key] = unquotedValue;
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading environment file: ${error.message}`);
    return {};
  }
}

/**
 * Parse DATABASE_URL and extract connection details
 * @param {string} databaseUrl - The DATABASE_URL connection string
 * @returns {Object} Parsed connection details
 */
parseDatabaseUrl(databaseUrl) {
  try {
    // Parse PostgreSQL connection string
    // Format: postgres://username:password@host:port/database
    const urlRegex = /^postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
    const match = databaseUrl.match(urlRegex);

    if (!match) {
      throw new Error('Invalid DATABASE_URL format');
    }

    const [, username, password, host, port, database] = match;

    return {
      username,
      // Mask password for security
      password: '••••••••',
      host,
      port,
      database
    };
  } catch (error) {
    console.error(`Error parsing DATABASE_URL: ${error.message}`);
    return null;
  }
}

/**
 * Log connection success message
 * @param {Object} connectionDetails - Parsed connection details
 */
