  console.log('='.repeat(60));
  console.log(`Host:     ${connectionDetails.host}:${connectionDetails.port}`);
  console.log(`Database: ${connectionDetails.database}`);
  console.log(`User:     ${connectionDetails.username}`);
  console.log(`Password: ${connectionDetails.password}`);
  console.log('='.repeat(60));
  console.log();
}

