#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from a ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationRunner {
  constructor(migrationsDir = './migrations') {
    this.migrationsDir = migrationsDir;
    this.migrationFiles = [];
  }

  /**
   * Read all SQL files from migrations directory
   * @returns {Array} Array of migration file objects with name and path
   */
  readMigrationFiles() {
    try {
      // Check if migrations directory exists
      if (!fs.existsSync(this.migrationsDir)) {
        console.error(`Error: Migrations directory "${this.migrationsDir}" not found.`);
        process.exit(1);
      }

      // Read all files from migrations directory
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for .sql files
      const sqlFiles = files.filter(file => file.endsWith('.sql'));

      if (sqlFiles.length === 0) {
        console.log('No migration files found.');
        return [];
      }

      // Create array of migration file objects
      this.migrationFiles = sqlFiles.map(file => ({
        name: file,
        path: path.join(this.migrationsDir, file),
        timestamp: this.extractTimestamp(file)
      }));

      return this.migrationFiles;
    } catch (error) {
      console.error(`Error reading migration files: ${error.message}`);
      process.exit(1);
    }
  }

  /**
   * Extract timestamp from filename for sorting
   * @param {string} filename - The migration filename
   * @returns {string} The timestamp or numeric prefix
   */
  extractTimestamp(filename) {
    // Common migration filename patterns:
    // 1. Number prefix: 001_description.sql, 002_description.sql
    // 2. Timestamp prefix: 20240115143000_description.sql
    // 3. Plain names: description.sql

    const match = filename.match(/^(\d+)_/);
    if (match) {
      return match[1];
    }
    return filename; // Return filename for alphabetical sorting as fallback
  }

  /**
   * Sort migration files in order
   * @returns {Array} Sorted array of migration files
   */
  sortMigrationFiles() {
    return this.migrationFiles.sort((a, b) => {
      // Compare numeric/timestamp prefixes first
      const aIsNumeric = /^\d+$/.test(a.timestamp);
      const bIsNumeric = /^\d+$/.test(b.timestamp);

      if (aIsNumeric && bIsNumeric) {
        // Both have numeric prefixes - compare as BigInt to handle large numbers
        return BigInt(a.timestamp) < BigInt(b.timestamp) ? -1 : 1;
      } else if (aIsNumeric && !bIsNumeric) {
        return -1; // Numeric prefixes come before non-numeric
      } else if (!aIsNumeric && bIsNumeric) {
        return 1; // Non-numeric come after numeric
      } else {
        // Both non-numeric - sort alphabetically
        return a.name.localeCompare(b.name);
      }
    });
  }

  /**
   * Read and display SQL content of a migration file
   * @param {Object} migration - Migration file object
   */
  readMigrationContent(migration) {
    try {
      const content = fs.readFileSync(migration.path, 'utf8');
      console.log(`\n--- Content of ${migration.name} ---`);
      console.log(content);
      console.log('--- End of content ---\n');
    } catch (error) {
      console.error(`Error reading ${migration.name}: ${error.message}`);
    }
  }

  /**
   * Run the migration simulation
   * @param {boolean} showContent - Whether to show SQL content
   */
  run(showContent = false) {
    console.log('=== Database Migration Script ===');
    console.log(`Reading migration files from: ${this.migrationsDir}`);
    console.log('='.repeat(50));

    // Read migration files
    const files = this.readMigrationFiles();

    if (files.length === 0) {
      return;
    }

    console.log(`Found ${files.length} migration file(s):`);

    // Sort files in order
    const sortedFiles = this.sortMigrationFiles();

    // Log each filename in order
    console.log('\nMigration files to apply (in order):');
    sortedFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file.name}`);
    });

    if (showContent) {
      console.log('\n' + '='.repeat(50));
      console.log('Migration SQL content:');
      console.log('='.repeat(50));

      sortedFiles.forEach(file => {
        this.readMigrationContent(file);
      });
    }

    console.log('\n' + '='.repeat(50));
    console.log('Migration simulation complete.');
    console.log(`Total migrations to apply: ${sortedFiles.length}`);
    console.log('='.repeat(50));

    // Note: This script only logs what would be applied
    console.log('\nNote: This is a simulation only. To actually apply migrations,');
    console.log('you would need to connect to a database and execute the SQL.');
  }
}

// Parse command line arguments
function parseArgs() {
  const args = process.argv.slice(2);
  const options = {
    showContent: false,
    help: false
  };

  for (const arg of args) {
    if (arg === '--show-content' || arg === '-c') {
      options.showContent = true;
    } else if (arg === '--help' || arg === '-h') {
      options.help = true;
    } else if (arg.startsWith('--dir=')) {
      options.dir = arg.replace('--dir=', '');
    }
  }

  return options;
}

// Show help message
function showHelp() {
  console.log(`
Database Migration Script

Usage: node migrate.js [options]

Options:
  -c, --show-content    Show SQL content of each migration file
  -h, --help           Show this help message
  --dir=<path>         Specify custom migrations directory (default: ./migrations)

Examples:
  node migrate.js                    # List migration files in order
  node migrate.js --show-content     # List files with SQL content
  node migrate.js --dir=./db-changes # Use custom migrations directory
  `);
}

// Main execution
function main() {
  const options = parseArgs();

