const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from a ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationRunner {
  constructor(migrationsDir = './migrations') {
    this.migrationsDir = migrationsDir;
    this.migrationFiles = [];
    this.databaseUrl = null;
  }

  /**
   * Read DATABASE_URL from .env.test file
   */
  loadDatabaseUrl() {
    const envFilePath = '.env.test';

    try {
      if (fs.existsSync(envFilePath)) {
        const envContent = fs.readFileSync(envFilePath, 'utf8');
        const lines = envContent.split('\n');

        for (const line of lines) {
          if (line.trim().startsWith('DATABASE_URL=')) {
            // Extract the DATABASE_URL value
            this.databaseUrl = line.trim().substring('DATABASE_URL='.length);

            // Remove quotes if present
            this.databaseUrl = this.databaseUrl.replace(/^["']|["']$/g, '');

            console.log(`✓ Loaded DATABASE_URL from ${envFilePath}`);
            return true;
          }
        }

        console.log(`⚠ DATABASE_URL not found in ${envFilePath}`);
        return false;
      } else {
        console.log(`⚠ ${envFilePath} file not found`);
        return false;
      }
    } catch (error) {
      console.error(`Error reading ${envFilePath}: ${error.message}`);
      return false;
    }
  }

  /**
   * Log database connection message (simulated)
   */
  logConnectionMessage() {
    if (this.databaseUrl) {
      // Parse the connection string for logging purposes
      try {
        // Extract basic info from the URL for logging
        const url = new URL(this.databaseUrl);
        const protocol = url.protocol.replace(':', '');
        const hostname = url.hostname;
        const port = url.port || (protocol === 'postgres' ? '5432' : 'default');
        const database = url.pathname.substring(1); // Remove leading slash
        const username = url.username;

        console.log(`✓ Connecting to ${protocol} database:`);
        console.log(`  Host: ${hostname}:${port}`);
        console.log(`  Database: ${database}`);
        console.log(`  User: ${username}`);
        console.log('✓ Connection established successfully\n');
      } catch (error) {
        // If URL parsing fails, just log the raw connection string (masked)
        const maskedUrl = this.maskSensitiveInfo(this.databaseUrl);
        console.log(`✓ Using connection string: ${maskedUrl}`);
        console.log('✓ Connection established successfully\n');
      }
    } else {
      console.log('⚠ No DATABASE_URL configured. Running in simulation mode only.\n');
    }
  }

  /**
   * Mask sensitive information in connection strings for logging
   */
  maskSensitiveInfo(connectionString) {
    // Simple masking for common connection string patterns
    return connectionString.replace(
      /:\/\/[^@]+@/g,
      match => {
        // Find the password in the match
        const parts = match.split(':');
        if (parts.length >= 3) {
          // Has username:password@ format
          const protocol = parts[0];
          const username = parts[1];
          const passwordAndRest = parts.slice(2).join(':');
          const atIndex = passwordAndRest.indexOf('@');

          if (atIndex !== -1) {
            const password = passwordAndRest.substring(0, atIndex);
            const rest = passwordAndRest.substring(atIndex);
            const maskedPassword = password.length > 4 
