        // Fallback - mask the entire middle part
        const atIndex = match.indexOf('@');
        if (atIndex !== -1) {
          return `${match.substring(0, match.indexOf('://') + 3)}***${match.substring(atIndex)}`;
        }

        return match;
      }
    );
  }

