/**
 * Read all values from .env.test file
 */
loadEnvValues() {
  const envFilePath = '.env.test';

  try {
    if (fs.existsSync(envFilePath)) {
      const envContent = fs.readFileSync(envFilePath, 'utf8');
      const lines = envContent.split('\n');
      this.envValues = {};

      for (const line of lines) {
        const trimmedLine = line.trim();

        // Skip empty lines and comments
        if (!trimmedLine || trimmedLine.startsWith('#')) {
          continue;
        }

        // Parse key=value pairs
        const equalsIndex = trimmedLine.indexOf('=');
        if (equalsIndex !== -1) {
          const key = trimmedLine.substring(0, equalsIndex);
          let value = trimmedLine.substring(equalsIndex + 1);

          // Remove quotes if present
          value = value.replace(/^["']|["']$/g, '');

          this.envValues[key] = value;

          // Store DATABASE_URL separately for convenience
          if (key === 'DATABASE_URL') {
            this.databaseUrl = value;
          }
        }
      }

      console.log(`✓ Loaded ${Object.keys(this.envValues).length} values from ${envFilePath}`);
      return true;
    } else {
      console.log(`⚠ ${envFilePath} file not found`);
      return false;
    }
  } catch (error) {
    console.error(`Error reading ${envFilePath}: ${error.message}`);
    return false;
  }
}

