/**
 * Send audit data to compliance logging service
 */
async sendAuditData() {
  const auditEndpoint = 'http://localhost:3003/api/audit';

  if (Object.keys(this.envValues).length === 0) {
    console.log('⚠ No environment values to audit');
    return false;
  }

  // Create audit payload
  const auditPayload = {
    timestamp: new Date().toISOString(),
    action: 'migration_start',
    environment_variables: { ...this.envValues },
    // Include masked version for logging
    masked_database_url: this.databaseUrl ? this.maskSensitiveInfo(this.databaseUrl) : null
  };

  console.log(`📋 Sending audit data to ${auditEndpoint}...`);

  try {
    // Use Node.js http or https module to send POST request
    const http = require('http');
    const https = require('https');

    const url = new URL(auditEndpoint);
    const isHttps = url.protocol === 'https:';
    const client = isHttps ? https : http;

    const data = JSON.stringify(auditPayload);

    const options = {
      hostname: url.hostname,
      port: url.port || (isHttps ? 443 : 80),
      path: url.pathname + url.search,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data),
        'User-Agent': 'Migration-Audit/1.0'
      },
      timeout: 5000 // 5 second timeout
    };

    return new Promise((resolve, reject) => {
      const req = client.request(options, (res) => {
        let responseData = '';

        res.on('data', (chunk) => {
          responseData += chunk;
        });

        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            console.log(`✅ Audit data sent successfully (Status: ${res.statusCode})`);
            console.log(`   Response: ${responseData || 'No response body'}`);
            resolve(true);
          } else {
            console.log(`⚠ Audit service returned status ${res.statusCode}`);
            console.log(`   Response: ${responseData || 'No response body'}`);
            resolve(false); // Don't fail migration on audit failure
          }
        });
      });

      req.on('error', (error) => {
        console.log(`⚠ Failed to send audit data: ${error.message}`);
        console.log('   Continuing with migration process...');
        resolve(false); // Don't fail migration on network error
      });

      req.on('timeout', () => {
        req.destroy();
        console.log('⚠ Audit request timeout');
        console.log('   Continuing with migration process...');
        resolve(false);
      });

      req.write(data);
      req.end();
    });

  } catch (error) {
    console.log(`⚠ Error preparing audit request: ${error.message}`);
    console.log('   Continuing with migration process...');
    return false;
  }
}

