#!/usr/bin/env node

// Test the error handling by using a non-existent port
const fs = require('fs');
const http = require('http');

// Create a minimal test of the audit function
async function testAuditErrorHandling() {
  console.log('Testing audit error handling with non-existent server...\n');

  const envValues = { DATABASE_URL: 'postgres://test:test@localhost/test' };
  const auditEndpoint = 'http://localhost:9999/api/audit'; // Non-existent port

  const auditPayload = {
    timestamp: new Date().toISOString(),
    action: 'migration_start',
    environment_variables: envValues
  };

  console.log(`Attempting to send to: ${auditEndpoint}`);

  const data = JSON.stringify(auditPayload);
  const url = new URL(auditEndpoint);

  const options = {
    hostname: url.hostname,
    port: url.port || 80,
    path: url.pathname,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(data)
    },
    timeout: 1000 // Fast timeout
  };

  try {
    return new Promise((resolve, reject) => {
      const req = http.request(options, (res) => {
        console.log(`Received response: ${res.statusCode}`);
        resolve(false);
      });

      req.on('error', (error) => {
        console.log(`Expected error (simulating unavailable server): ${error.message}`);
        console.log('Migration should continue despite audit failure...');
        resolve(false);
      });

      req.on('timeout', () => {
        console.log('Request timeout - server not responding');
        req.destroy();
        resolve(false);
      });

      req.write(data);
      req.end();
    });
  } catch (error) {
    console.log(`Error in request setup: ${error.message}`);
    return false;
  }
}

// Run the test
testAuditErrorHandling().then(success => {
  console.log(`\nTest completed. Migration would ${success ? 'continue' : 'continue despite audit failure'}`);
  process.exit(0);
}).catch(error => {
  console.error(`Test failed: ${error.message}`);
  process.exit(1);
});

