#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

class MigrationRunner {
  constructor() {
    this.migrationsDir = path.join(__dirname, 'migrations');
    this.migrations = [];
  }

  // Read all SQL files from migrations directory
  readMigrations() {
    try {
      // Check if migrations directory exists
      if (!fs.existsSync(this.migrationsDir)) {
        console.error(`Error: Migrations directory not found at ${this.migrationsDir}`);
        console.log('Creating migrations directory...');
        fs.mkdirSync(this.migrationsDir, { recursive: true });
        console.log('No migration files found.');
        return [];
      }

      // Read all files in migrations directory
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for SQL files and sort them
      const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort((a, b) => {
          // Sort by numeric prefix if present
          const numA = this.extractNumber(a);
          const numB = this.extractNumber(b);

          if (numA !== null && numB !== null) {
            return numA - numB;
          }
          // Fallback to alphabetical sort
          return a.localeCompare(b);
        });

      if (sqlFiles.length === 0) {
        console.log('No SQL migration files found in migrations directory.');
      }

      return sqlFiles;
    } catch (error) {
      console.error(`Error reading migrations directory: ${error.message}`);
      return [];
    }
  }

  // Extract numeric prefix from filename
  extractNumber(filename) {
    const match = filename.match(/^(\d+)_/);
    return match ? parseInt(match[1], 10) : null;
  }

  // Log migration files that would be applied
  logMigrations() {
    console.log('=== Database Migration Script ===');
    console.log(`Reading migration files from: ${this.migrationsDir}`);
    console.log('----------------------------------');

    const migrationFiles = this.readMigrations();

    if (migrationFiles.length === 0) {
      console.log('No migration files to apply.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s) to apply:`);
    console.log('----------------------------------');

    migrationFiles.forEach((file, index) => {
      const filePath = path.join(this.migrationsDir, file);
      console.log(`${index + 1}. ${file}`);

      // Optional: Show first line of SQL for context
      try {
        const content = fs.readFileSync(filePath, 'utf8');
        const firstLine = content.split('\n')[0].trim();
        if (firstLine) {
          console.log(`   Preview: ${firstLine.substring(0, 60)}${firstLine.length > 60 ? '...' : ''}`);
        }
      } catch (error) {
        console.log(`   [Could not read file for preview]`);
      }
    });

    console.log('----------------------------------');
    console.log(`Total: ${migrationFiles.length} migration file(s)`);
    console.log('==================================');
  }

  // Main entry point
  run() {
    this.logMigrations();
  }
}

// Run the script if called directly
if (require.main === module) {
  const runner = new MigrationRunner();
  runner.run();
}

module.exports = MigrationRunner;

// Example of programmatic usage
