#!/usr/bin/env node

/**
 * Database Migration Script
 * 
 * This script reads SQL files from a ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

class MigrationRunner {
  constructor() {
    this.migrationsDir = path.join(__dirname, 'migrations');
  }

  /**
   * Read all SQL files from the migrations directory
   * @returns {Array} Sorted list of migration file objects
   */
  readMigrationFiles() {
    try {
      // Check if migrations directory exists
      if (!fs.existsSync(this.migrationsDir)) {
        console.error(`Error: Migrations directory '${this.migrationsDir}' does not exist.`);
        console.log('Creating migrations directory...');
        fs.mkdirSync(this.migrationsDir, { recursive: true });
        console.log('Migrations directory created. Add your SQL files to proceed.');
        return [];
      }

      // Read all files in the migrations directory
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for SQL files
      const sqlFiles = files.filter(file => file.endsWith('.sql'));

      if (sqlFiles.length === 0) {
        console.log('No SQL migration files found in the migrations directory.');
        return [];
      }

      // Create file objects with metadata
      const migrationFiles = sqlFiles.map(file => {
        const filePath = path.join(this.migrationsDir, file);
        const stats = fs.statSync(filePath);

        return {
          filename: file,
          path: filePath,
          size: stats.size,
          modified: stats.mtime
        };
      });

      // Sort files by name (which should include version numbers)
      migrationFiles.sort((a, b) => {
        return a.filename.localeCompare(b.filename);
      });

      return migrationFiles;
    } catch (error) {
      console.error('Error reading migration files:', error.message);
      return [];
    }
  }

  /**
   * Log migration files in order
   */
  logMigrations() {
    console.log('=== Database Migration Script ===');
    console.log(`Reading migration files from: ${this.migrationsDir}\n`);

    const migrationFiles = this.readMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migrations to apply.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    // Log each migration file in order
    migrationFiles.forEach((file, index) => {
      console.log(`[${index + 1}/${migrationFiles.length}] ${file.filename}`);
      console.log(`   Path: ${file.path}`);
      console.log(`   Size: ${file.size} bytes`);
      console.log(`   Last Modified: ${file.modified.toLocaleString()}`);
      console.log();
    });

    console.log('=== Migration Summary ===');
    console.log(`Total migrations to apply: ${migrationFiles.length}`);
    console.log('To apply these migrations, you would execute the SQL files in the order shown above.');
  }

  /**
   * Optional: Read and display SQL content (for debugging)
   * @param {string} filePath - Path to the SQL file
   */
  readSqlContent(filePath) {
    try {
      return fs.readFileSync(filePath, 'utf8');
    } catch (error) {
      console.error(`Error reading SQL file ${filePath}:`, error.message);
      return null;
    }
  }
}

// Main execution
if (require.main === module) {
  const runner = new MigrationRunner();
  runner.logMigrations();
}

// Export for testing or programmatic use
module.exports = MigrationRunner;

