#!/usr/bin/env node

/**
 * Database Migration Script
 * 
 * This script reads SQL files from a ./migrations/ directory
 * and logs each filename it would apply, in order.
 * It also reads DATABASE_URL from .env.test and logs connection status.
 */

const fs = require('fs');
const path = require('path');

class MigrationRunner {
  constructor() {
    this.migrationsDir = path.join(__dirname, 'migrations');
    this.envFile = '.env.test';
    this.databaseUrl = null;
  }

  /**
   * Read DATABASE_URL from .env.test file
   * @returns {string|null} The database URL or null if not found
   */
  readDatabaseUrl() {
    try {
      const envPath = path.join(__dirname, this.envFile);

      if (!fs.existsSync(envPath)) {
        console.error(`Warning: Environment file '${this.envFile}' not found.`);
        return null;
      }

      const envContent = fs.readFileSync(envPath, 'utf8');

      // Parse the .env file looking for DATABASE_URL
      const lines = envContent.split('\n');
      for (const line of lines) {
        // Skip comments and empty lines
        const trimmedLine = line.trim();
        if (trimmedLine.startsWith('#') || trimmedLine.length === 0) {
          continue;
        }

        // Look for DATABASE_URL
        if (trimmedLine.startsWith('DATABASE_URL=')) {
          const dbUrl = trimmedLine.substring('DATABASE_URL='.length).trim();
          // Remove surrounding quotes if present
          return dbUrl.replace(/^['"]|['"]$/g, '');
        }
      }

      console.error(`Warning: DATABASE_URL not found in '${this.envFile}'.`);
      return null;
    } catch (error) {
      console.error(`Error reading environment file '${this.envFile}':`, error.message);
      return null;
    }
  }

  /**
   * Log database connection status
   */
  logConnectionStatus() {
    this.databaseUrl = this.readDatabaseUrl();

    if (this.databaseUrl) {
      console.log(`✓ Successfully read DATABASE_URL from '${this.envFile}'`);

      // Parse and display connection details (without sensitive parts)
      try {
        // Parse the PostgreSQL connection string
        const url = new URL(this.databaseUrl);
        const username = url.username;
        const host = url.hostname;
        const port = url.port || '5432';
        const database = url.pathname.substring(1); // Remove leading slash

        console.log(`  Database: ${database}`);
        console.log(`  Host: ${host}:${port}`);
        console.log(`  User: ${username}`);
        console.log(`  Connection string: ${url.protocol}//${username}:***@${host}:${port}/${database}`);

        // Log success message
        console.log(`✓ Would connect to database successfully\n`);
      } catch (error) {
        // If URL parsing fails, show masked version
        const maskedUrl = this.maskSensitiveData(this.databaseUrl);
        console.log(`  Using connection string: ${maskedUrl}`);
        console.log(`✓ Would connect to database successfully (connection string parsed)\n`);
      }
    } else {
      console.log(`⚠ No DATABASE_URL found in '${this.envFile}'`);
      console.log(`  Please ensure DATABASE_URL is set in ${this.envFile}`);
      console.log(`  Proceeding with migration logging only (no database operations)\n`);
    }
  }

  /**
   * Mask sensitive data in connection strings
   * @param {string} url - The connection string
   * @returns {string} Masked connection string
   */
  maskSensitiveData(url) {
    // Simple masking for passwords
    return url.replace(/:([^:@]+)@/, ':***@');
  }

  /**
   * Read all SQL files from the migrations directory
   * @returns {Array} Sorted list of migration file objects
   */
  readMigrationFiles() {
    try {
      // Check if migrations directory exists
      if (!fs.existsSync(this.migrationsDir)) {
        console.error(`Error: Migrations directory '${this.migrationsDir}' does not exist.`);
        console.log('Creating migrations directory...');
        fs.mkdirSync(this.migrationsDir, { recursive: true });
        console.log('Migrations directory created. Add your SQL files to proceed.');
        return [];
      }

      // Read all files in the migrations directory
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for SQL files
      const sqlFiles = files.filter(file => file.endsWith('.sql'));

      if (sqlFiles.length === 0) {
        console.log('No SQL migration files found in the migrations directory.');
        return [];
      }

      // Create file objects with metadata
      const migrationFiles = sqlFiles.map(file => {
        const filePath = path.join(this.migrationsDir, file);
        const stats = fs.statSync(filePath);

        return {
          filename: file,
          path: filePath,
          size: stats.size,
          modified: stats.mtime
        };
      });

      // Sort files by name (which should include version numbers)
      migrationFiles.sort((a, b) => {
        return a.filename.localeCompare(b.filename);
      });

      return migrationFiles;
    } catch (error) {
      console.error('Error reading migration files:', error.message);
      return [];
    }
  }

  /**
   * Log migration files in order
   */
  logMigrations() {
    console.log('=== Database Migration Script ===\n');

    // First, log connection status
    console.log('=== Database Connection ===');
    this.logConnectionStatus();

    console.log('=== Migration Files ===');
    console.log(`Reading migration files from: ${this.migrationsDir}\n`);

    const migrationFiles = this.readMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migrations to apply.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    // Log each migration file in order
    migrationFiles.forEach((file, index) => {
      console.log(`[${index + 1}/${migrationFiles.length}] ${file.filename}`);
      console.log(`   Path: ${file.path}`);
      console.log(`   Size: ${file.size} bytes`);
      console.log(`   Last Modified: ${file.modified.toLocaleString()}`);
      console.log();
    });

    console.log('=== Migration Summary ===');
    console.log(`Total migrations to apply: ${migrationFiles.length}`);
    if (this.databaseUrl) {
      console.log(`Status: Ready to apply ${migrationFiles.length} migration(s) to the database`);
      console.log(`Connection: Using DATABASE_URL from ${this.envFile}`);
    } else {
      console.log(`Status: ${migrationFiles.length} migration(s) identified (no database connection)`);
      console.log(`Note: Set DATABASE_URL in ${this.envFile} to enable database operations`);
    }
  }

  /**
   * Optional: Read and display SQL content (for debugging)
   * @param {string} filePath - Path to the SQL file
   */
  readSqlContent(filePath) {
    try {
      return fs.readFileSync(filePath, 'utf8');
    } catch (error) {
      console.error(`Error reading SQL file ${filePath}:`, error.message);
      return null;
    }
  }
}

// Main execution
if (require.main === module) {
  const runner = new MigrationRunner();
  runner.logMigrations();
}

// Export for testing or programmatic use
module.exports = MigrationRunner;

