/**
 * Send audit data to the migration audit service
 * @param {Object} envVars - All environment variables from .env.test
 * @returns {Promise<boolean>} True if audit was successful, false otherwise
 */
async sendAuditData(envVars) {
  if (!envVars || Object.keys(envVars).length === 0) {
    console.log('⚠ No environment variables to audit');
    return false;
  }

  const auditUrl = 'http://localhost:3003/api/audit';
  const auditData = {
    timestamp: new Date().toISOString(),
    script: 'migrate.js',
    action: 'migration_preflight',
    env_variables: envVars,
    metadata: {
      migrations_dir: this.migrationsDir,
      has_migrations: fs.existsSync(this.migrationsDir)
    }
  };

  return new Promise((resolve) => {
    const data = JSON.stringify(auditData);

    // Parse the URL
    const url = new URL(auditUrl);
    const options = {
      hostname: url.hostname,
      port: url.port || 3003,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data),
        'User-Agent': 'Migration-Audit-Script/1.0'
      },
      timeout: 10000 // 10 second timeout
    };

    console.log(`📋 Sending audit data to: ${auditUrl}`);

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✓ Audit data sent successfully (Status: ${res.statusCode})`);
          try {
            const response = JSON.parse(responseData);
            if (response.message) {
              console.log(`  Audit service response: ${response.message}`);
            }
          } catch (e) {
            // Response is not JSON, that's ok
          }
          resolve(true);
        } else {
          console.error(`⚠ Audit service returned error status: ${res.statusCode}`);
          console.error(`  Response: ${responseData || 'No response body'}`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.error(`⚠ Failed to send audit data: ${error.message}`);
      console.log(`  Note: Audit service at ${auditUrl} may not be running`);
      console.log(`  Continuing with migration logging...`);
      resolve(false);
    });

    req.on('timeout', () => {
      console.error('⚠ Audit request timed out after 10 seconds');
      req.destroy();
      resolve(false);
    });

    req.write(data);
    req.end();
  });
}

