      const envVars = {};

      // Parse the .env file
      const lines = envContent.split('\n');
      for (const line of lines) {
        const trimmedLine = line.trim();
        if (trimmedLine.startsWith('#') || trimmedLine.length === 0) {
          continue;
        }

        const equalsIndex = trimmedLine.indexOf('=');
        if (equalsIndex > 0) {
          const key = trimmedLine.substring(0, equalsIndex).trim();
          let value = trimmedLine.substring(equalsIndex + 1).trim();
          value = value.replace(/^['"]|['"]$/g, '');
          envVars[key] = value;
        }
      }

      return envVars;
    } catch (error) {
      console.error(`Error reading environment file '${this.envFile}':`, error.message);
      return null;
    }
  }

  async sendAuditData(envVars) {
    if (!envVars || Object.keys(envVars).length === 0) {
      console.log('⚠ No environment variables to audit');
      return false;
    }

    // Use a non-existent port to test error handling
    const auditUrl = 'http://localhost:9999/api/audit';
    const auditData = {
      timestamp: new Date().toISOString(),
      env_variables: envVars
    };

    return new Promise((resolve) => {
      const data = JSON.stringify(auditData);
      const url = new URL(auditUrl);
      const options = {
        hostname: url.hostname,
        port: url.port || 9999,
        path: url.pathname,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(data)
        },
        timeout: 3000
      };

      console.log(`📋 Sending audit data to: ${auditUrl}`);

      const req = http.request(options, (res) => {
        let responseData = '';
        res.on('data', (chunk) => {
          responseData += chunk;
        });
        res.on('end', () => {
          console.log(`✓ Audit data sent successfully (Status: ${res.statusCode})`);
          resolve(true);
        });
      });

      req.on('error', (error) => {
        console.error(`⚠ Failed to send audit data: ${error.message}`);
        console.log(`  Note: Audit service at ${auditUrl} may not be running`);
        console.log(`  Continuing with migration logging...`);
        resolve(false);
      });

      req.on('timeout', () => {
        console.error('⚠ Audit request timed out after 3 seconds');
        req.destroy();
        resolve(false);
      });

      req.write(data);
      req.end();
    });
  }

  async run() {
    console.log('=== Testing Audit Error Handling ===\n');

    const envVars = this.readEnvFile();
    if (envVars) {
      console.log(`Found ${Object.keys(envVars).length} environment variables`);
      await this.sendAuditData(envVars);
    }
  }
}

