const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */
function main() {
    const migrationsDir = './migrations';

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.error(`Error: Migrations directory '${migrationsDir}' does not exist.`);
        console.log('Creating migrations directory...');
        try {
            fs.mkdirSync(migrationsDir, { recursive: true });
            console.log(`Created '${migrationsDir}' directory.`);
            console.log('Please add SQL migration files to this directory.');
            return;
        } catch (error) {
            console.error(`Failed to create migrations directory: ${error.message}`);
            process.exit(1);
        }
    }

    console.log('Reading migration files from:', path.resolve(migrationsDir));

    // Read all files from the migrations directory
    let files;
    try {
        files = fs.readdirSync(migrationsDir);
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        process.exit(1);
    }

    // Filter for SQL files
    const sqlFiles = files.filter(file => file.endsWith('.sql'));

    if (sqlFiles.length === 0) {
        console.log('No SQL migration files found in the migrations directory.');
        console.log('Please add .sql files to the ./migrations/ directory.');
        return;
    }

    console.log(`Found ${sqlFiles.length} SQL migration file(s):`);

    // Sort files in alphabetical order (assuming proper naming convention like 001_initial.sql, 002_add_users.sql)
    const sortedFiles = sqlFiles.sort((a, b) => {
        // Simple alphabetical sort - for better sorting, you might want to extract numbers
        return a.localeCompare(b);
    });

    // Log each migration file that would be applied
    console.log('\nMigrations that would be applied (in order):');
    console.log('===========================================');

    sortedFiles.forEach((file, index) => {
        const filePath = path.join(migrationsDir, file);
        try {
            const stats = fs.statSync(filePath);
            console.log(`${index + 1}. ${file} (${stats.size} bytes)`);
        } catch (error) {
            console.log(`${index + 1}. ${file} (ERROR: ${error.message})`);
        }
    });

    console.log('===========================================');
    console.log(`Total: ${sortedFiles.length} migration(s) ready to be applied.`);
    console.log('\nNote: This script only lists migration files.');
    console.log('To actually apply migrations, implement database connection logic.');
}

// Run the main function
if (require.main === module) {
    main();
}

module.exports = { main };

