    console.log('\n' + '='.repeat(50));
    console.log(`Total: ${sortedFiles.length} migration(s) ready to be applied.`);

    if (!verbose) {
        console.log('\nTip: Use --verbose flag to see full SQL content.');
    }

    console.log('\nNote: This is a dry-run. No migrations have been applied.');
    console.log('To actually apply migrations, implement database connection logic.');
