#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from a ./migrations/ directory
 * and logs each filename it would apply, in order.
 */
async function migrate() {
    const migrationsDir = './migrations';

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.error(`Error: Migrations directory '${migrationsDir}' not found.`);
        console.log('Creating migrations directory...');
        fs.mkdirSync(migrationsDir, { recursive: true });
        console.log('Please add SQL migration files to the directory and run again.');
        return;
    }

    // Read all files in migrations directory
    let files;
    try {
        files = fs.readdirSync(migrationsDir);
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        process.exit(1);
    }

    // Filter for SQL files (support .sql extension)
    const sqlFiles = files.filter(file => file.endsWith('.sql'));

    if (sqlFiles.length === 0) {
        console.log('No SQL migration files found in ./migrations/ directory.');
        console.log('Please add SQL files with .sql extension to the migrations directory.');
        return;
    }

    // Sort files to ensure they're applied in order
    const sortedFiles = sqlFiles.sort();

    console.log(`Found ${sortedFiles.length} migration file(s) in ${migrationsDir}:`);
    console.log('='.repeat(50));

    // Log each migration file in order
    sortedFiles.forEach((filename, index) => {
        const filePath = path.join(migrationsDir, filename);
        const fileNumber = (index + 1).toString().padStart(3, '0');
        console.log(`${fileNumber}. ${filename}`);

        // Optional: Show first few lines of each SQL file
        try {
            const content = fs.readFileSync(filePath, 'utf8');
            const lines = content.split('\n').slice(0, 3);
            if (lines.some(line => line.trim() !== '')) {
                console.log('   Preview: ' + lines.map(l => l.trim()).filter(l => l).join(' ').substring(0, 60) + '...');
            }
        } catch (error) {
            console.log(`   Error reading file: ${error.message}`);
        }
    });

    console.log('='.repeat(50));
    console.log(`Total: ${sortedFiles.length} migration(s) would be applied.`);

    // Ask for confirmation if we wanted to actually apply them
    // (For this exercise, we're just logging filenames)
}

// Run the migration function
if (require.main === module) {
    migrate().catch(error => {
        console.error(`Migration failed: ${error.message}`);
        process.exit(1);
    });
}

module.exports = { migrate };

