#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Read environment variables from .env.test file
 * @returns {Object} Parsed environment variables
 */
function loadEnvFile() {
    const envFilePath = '.env.test';

    if (!fs.existsSync(envFilePath)) {
        console.error(`Error: Environment file '${envFilePath}' not found.`);
        process.exit(1);
    }

    try {
        const envContent = fs.readFileSync(envFilePath, 'utf8');
        const envVars = {};

        // Parse each line
        envContent.split('\n').forEach(line => {
            line = line.trim();

            // Skip empty lines and comments
            if (!line || line.startsWith('#')) {
                return;
            }

            // Parse KEY=VALUE format
            const equalsIndex = line.indexOf('=');
            if (equalsIndex !== -1) {
                const key = line.substring(0, equalsIndex).trim();
                const value = line.substring(equalsIndex + 1).trim();
                envVars[key] = value;
            }
        });

        return envVars;
    } catch (error) {
        console.error(`Error reading environment file: ${error.message}`);
        process.exit(1);
    }
}

/**
 * Parse database URL to extract connection details
 * @param {string} databaseUrl - Database connection URL
 * @returns {Object} Parsed connection details
 */
function parseDatabaseUrl(databaseUrl) {
    try {
        // Parse URL format: postgres://username:password@host:port/database
        const urlPattern = /^([^:]+):\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
        const match = databaseUrl.match(urlPattern);

        if (!match) {
            throw new Error('Invalid database URL format');
        }

        const [, protocol, username, password, host, port, database] = match;

        // Mask password for logging
        const maskedPassword = password.replace(/./g, '*');
        const maskedUrl = `${protocol}://${username}:${maskedPassword}@${host}:${port}/${database}`;

        return {
            protocol,
            username,
            password,
            host,
            port: parseInt(port, 10),
            database,
            maskedUrl
        };
    } catch (error) {
        console.error(`Error parsing DATABASE_URL: ${error.message}`);
