#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.
 */

class MigrationRunner {
  constructor() {
    this.migrationsDir = path.join(__dirname, './migrations');
  }

  // Get all migration files sorted by filename
  getMigrationFiles() {
    try {
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for .sql files
      const sqlFiles = files.filter(file => file.endsWith('.sql'));

      // Sort files by name (numerical prefix first)
      sqlFiles.sort((a, b) => {
        // Extract numbers from filename for better sorting
        const numA = this.extractNumber(a);
        const numB = this.extractNumber(b);

        if (numA !== null && numB !== null) {
          return numA - numB;
        }

        // Fallback to alphabetical sorting
        return a.localeCompare(b);
      });

      return sqlFiles;
    } catch (error) {
      if (error.code === 'ENOENT') {
        console.error(`Error: Migrations directory not found at ${this.migrationsDir}`);
        console.error('Please create a ./migrations/ directory with SQL migration files.');
      } else {
        console.error(`Error reading migrations directory: ${error.message}`);
      }
      return [];
    }
  }

  // Extract number from filename (e.g., "001_create_table.sql" -> 1)
  extractNumber(filename) {
    const match = filename.match(/^(\d+)/);
    return match ? parseInt(match[1], 10) : null;
  }

  // Read and log the migration file content (optional)
  readMigrationFile(filename) {
    const filePath = path.join(this.migrationsDir, filename);
    try {
      return fs.readFileSync(filePath, 'utf8');
    } catch (error) {
      console.error(`Error reading migration file ${filename}: ${error.message}`);
      return '';
    }
  }

  // Display migration information
  displayMigrationInfo(filename, index) {
    const content = this.readMigrationFile(filename);
    const lines = content.split('\n');
    const firstLine = lines[0] || '';

    console.log(`[${index + 1}] ${filename}`);

    // Show first line comment if available
    if (firstLine.startsWith('--')) {
      console.log(`   ${firstLine.trim()}`);
    }

    // Optional: Show a preview of the SQL
    const sqlPreview = content.replace(/\s+/g, ' ').trim().substring(0, 80);
    if (sqlPreview) {
      console.log(`   SQL preview: ${sqlPreview}${sqlPreview.length === 80 ? '...' : ''}`);
    }

    console.log(); // Empty line for readability
  }

  // Run the migrations
  run() {
    console.log('=== Database Migration Script ===\n');
    console.log('Scanning migrations directory...\n');

    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migration files found.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    // Display all migrations in order
    migrationFiles.forEach((filename, index) => {
      this.displayMigrationInfo(filename, index);
    });

    console.log('=== Summary ===');
    console.log(`Total migrations: ${migrationFiles.length}`);
    console.log('\nNote: This script only logs what would be applied.');
    console.log('To actually apply migrations, implement database connection logic.');
  }
}

// Main execution
if (require.main === module) {
  const runner = new MigrationRunner();
  runner.run();
}

module.exports = MigrationRunner;

