#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Create a test .env file with bad URL
const testEnvFile = path.join(__dirname, '.env.test.bad');
fs.writeFileSync(testEnvFile, 'DATABASE_URL=not-a-valid-url\n');

console.log('Testing with invalid DATABASE_URL...\n');

const envFile = testEnvFile;
const migrationsDir = path.join(__dirname, 'migrations');

function readDatabaseUrl() {
  try {
    if (!fs.existsSync(envFile)) {
      console.log('No env file found.');
      return null;
    }

    const envContent = fs.readFileSync(envFile, 'utf8');
    const lines = envContent.split('\n');

    for (const line of lines) {
      const trimmedLine = line.trim();
      if (!trimmedLine || trimmedLine.startsWith('#')) continue;

      if (trimmedLine.startsWith('DATABASE_URL=')) {
        const databaseUrl = trimmedLine.substring('DATABASE_URL='.length).trim();
        console.log(`Found DATABASE_URL: "${databaseUrl}"`);

        try {
          const url = new URL(databaseUrl);
          console.log(`Parsed successfully: ${url.protocol}`);
        } catch (parseError) {
          console.log(`Error parsing URL: ${parseError.message}`);
          console.log(`Will use raw value: ${databaseUrl.substring(0, 30)}`);
        }
        return databaseUrl;
      }
    }

    return null;

  } catch (error) {
    console.error(`Error: ${error.message}`);
    return null;
  }
}

readDatabaseUrl();

// Clean up
fs.unlinkSync(testEnvFile);

