// Read all environment variables from .env.test file
readEnvVariables() {
  try {
    if (!fs.existsSync(this.envFile)) {
      console.error(`Error: Environment file not found at ${this.envFile}`);
      return {};
    }

    const envContent = fs.readFileSync(this.envFile, 'utf8');
    const lines = envContent.split('\n');
    const envVars = {};

    for (const line of lines) {
      // Skip comments and empty lines
      const trimmedLine = line.trim();
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      // Parse key=value pairs
      const equalsIndex = trimmedLine.indexOf('=');
      if (equalsIndex === -1) {
        continue; // Skip lines without =
      }

      const key = trimmedLine.substring(0, equalsIndex).trim();
      const value = trimmedLine.substring(equalsIndex + 1).trim();
      envVars[key] = value;
    }

    return envVars;

  } catch (error) {
    console.error(`Error reading environment file: ${error.message}`);
    return {};
  }
}

// Read just DATABASE_URL (for backward compatibility)
readDatabaseUrl() {
  const envVars = this.readEnvVariables();
  return envVars.DATABASE_URL || null;
}

