#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from ./migrations/ directory
 * and logs each filename in order.
 */

class MigrationRunner {
    constructor() {
        this.migrationsDir = './migrations';
    }

    /**
     * Get all SQL migration files from the migrations directory
     * @returns {Array} Array of migration file info objects
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Error: Migrations directory '${this.migrationsDir}' not found`);
                return [];
            }

            // Read directory contents
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files and get full file info
            const migrationFiles = files
                .filter(file => file.endsWith('.sql'))
                .map(file => {
                    const filePath = path.join(this.migrationsDir, file);
                    const stats = fs.statSync(filePath);

                    return {
                        filename: file,
                        path: filePath,
                        size: stats.size,
                        modified: stats.mtime
                    };
                })
                // Sort files by name (assuming numerical or timestamp prefix)
                .sort((a, b) => {
                    // Simple lexical sort which works well with numeric prefixes
                    // For more complex sorting, consider parsing timestamps or numbers
                    return a.filename.localeCompare(b.filename);
                });

            return migrationFiles;

        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            return [];
        }
    }

    /**
     * Read the content of a migration file
     * @param {string} filePath - Path to the SQL file
     * @returns {string} File content
     */
    readMigrationFile(filePath) {
        try {
            return fs.readFileSync(filePath, 'utf8');
        } catch (error) {
            console.error(`Error reading migration file ${filePath}: ${error.message}`);
            return null;
        }
    }

    /**
     * Log migration information
     * @param {Object} migration - Migration file info
     * @param {number} index - Index of the migration
     */
    logMigration(migration, index) {
        console.log(`[${String(index + 1).padStart(3, '0')}] ${migration.filename}`);
        console.log(`     Path: ${migration.path}`);
        console.log(`     Size: ${migration.size} bytes`);
        console.log(`     Modified: ${migration.modified.toLocaleString()}`);

        // Read and show first few lines if file is small
        if (migration.size > 0 && migration.size < 10000) {
            const content = this.readMigrationFile(migration.path);
            if (content) {
                const lines = content.split('\n').slice(0, 3);
                const preview = lines.join('\n').trim();
                if (preview) {
                    console.log(`     Preview: ${preview}`);
                }
            }
        }

        console.log(); // Empty line for readability
    }

    /**
     * Run the migration script
     */
    run() {
        console.log('=== Database Migration Script ===\n');
        console.log(`Reading migrations from: ${path.resolve(this.migrationsDir)}\n`);
        console.log('Migrations to apply (in order):\n');

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migration files found.');
            return;
        }

        console.log(`Found ${migrationFiles.length} migration file(s):\n`);

        // Log each migration file
        migrationFiles.forEach((migration, index) => {
            this.logMigration(migration, index);
        });

        console.log('=== Summary ===');
        console.log(`Total migrations to apply: ${migrationFiles.length}`);
        console.log(`First migration: ${migrationFiles[0]?.filename || 'N/A'}`);
        console.log(`Last migration: ${migrationFiles[migrationFiles.length - 1]?.filename || 'N/A'}`);

        // Show a preview of what would be executed
        console.log('\n=== Simulated Execution (Would Apply) ===');
        console.log('NOTE: This script only logs what would be applied.');
        console.log('      To actually execute migrations, implement database connection logic.\n');

        migrationFiles.forEach((migration, index) => {
            console.log(`[${String(index + 1).padStart(3, '0')}] Would apply: ${migration.filename}`);
        });
    }
}

// Main execution
if (require.main === module) {
    const runner = new MigrationRunner();
    runner.run();
}

// Export for testing or programmatic use
module.exports = MigrationRunner;

