#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script that:
 * 1. Reads DATABASE_URL from .env.test
 * 2. Logs a simulated connection success message
 * 3. Reads SQL files from ./migrations/ directory
 * 4. Logs each filename it would apply, in order
 */

class MigrationScript {
    constructor() {
        this.migrationsDir = './migrations';
        this.envFile = '.env.test';
    }

    /**
     * Read DATABASE_URL from .env.test file
     * @returns {string|null} Database URL or null if not found
     */
    readDatabaseUrl() {
        try {
            if (!fs.existsSync(this.envFile)) {
                console.warn(`Warning: ${this.envFile} not found`);
                return null;
            }

            const content = fs.readFileSync(this.envFile, 'utf8');

            // Look for DATABASE_URL in the file
            const match = content.match(/DATABASE_URL\s*=\s*['"]?([^'"\s]+)['"]?/);

            if (match) {
                const databaseUrl = match[1];
                console.log(`Found DATABASE_URL in ${this.env.file}`);
                return databaseUrl;
            }

            console.warn(`DATABASE_URL not found in ${this.envFile}`);
            return null;

        } catch (error) {
            console.error(`Error reading ${this.envFile}: ${error.message}`);
            return null;
        }
    }

    /**
     * Simulate database connection (just log success message)
     * @param {string} databaseUrl - Database connection URL
     */
    simulateConnection(databaseUrl) {
        console.log('\n=== Database Connection ===');

        if (!databaseUrl) {
            console.log('No DATABASE_URL configured.');
            return false;
        }

        console.log(`Using DATABASE_URL from ${this.envFile}`);

        try {
            // Parse URL to show details (but don't actually connect)
            const url = new URL(databaseUrl);
            console.log(`Database: ${url.hostname}${url.pathname}`);

            // Log success message
            console.log('\n✅ Successfully connected to database (simulated)');
            console.log('   Note: This is simulation only - no actual connection was made.');

            return true;

        } catch (error) {
            console.error(`Invalid DATABASE_URL format: ${error.message}`);
            return false;
        }
    }

    /**
     * Get migration files in order
     * @returns {Array} Sorted array of SQL filenames
     */
    getMigrationFiles() {
        try {
            if (!fs.existsSync(this.migrationsDir)) {
                throw new Error(`Migrations directory '${this.migrationsDir}' not found`);
            }

            const files = fs.readdirSync(this.migrationsDir);
            const sqlFiles = files
                .filter(file => file.endsWith('.sql'))
                .sort(); // Lexical sort works with numbered/timestamped filenames

            return sqlFiles;

        } catch (error) {
            console.error(`Error: ${error.message}`);
            process.exit(1);
        }
    }

    /**
     * Run the migration script
     */
    run() {
        console.log('=== Database Migration Script ===\n');

        // Read DATABASE_URL and simulate connection
        const databaseUrl = this.readDatabaseUrl();
        this.simulateConnection(databaseUrl);

        console.log('\n=== Migration Files ===');

        // Get migration files
        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No SQL migration files found.');
            return;
        }

        console.log(`\nMigrations to apply (${migrationFiles.length} files):\n`);

        // Log each filename in order
        migrationFiles.forEach((filename, index) => {
            console.log(`${index + 1}. ${filename}`);
        });

        console.log('\n✅ Migration logging complete');
        console.log(`   Database: ${databaseUrl ? 'Configured' : 'Not configured'}`);
        console.log(`   Files to apply: ${migrationFiles.length}`);
    }
}

// Run the script
if (require.main === module) {
    const script = new MigrationScript();
    script.run();
}

module.exports = MigrationScript;

