#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Migration script that:
 * 1. Reads DATABASE_URL and all other values from .env.test
 * 2. POSTs them as JSON to http://localhost:3003/api/audit for compliance logging
 * 3. Logs success/failure of audit
 * 4. Reads SQL files from ./migrations/ directory
 * 5. Logs each filename it would apply, in order
 */

// Configuration
const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';
const AUDIT_URL = 'http://localhost:3003/api/audit';

// Main function
async function main() {
    console.log('Starting migration script with audit logging...\n');

    try {
        // 1. Read .env.test file
        const envValues = readEnvFile(ENV_FILE);
        console.log(`Read ${Object.keys(envValues).length} values from ${ENV_FILE}`);

        // 2. Send audit data
        console.log('\n--- Sending audit data ---');
        const auditSuccess = await sendAuditData(envValues);

        if (auditSuccess) {
            console.log('✅ Audit data sent successfully');
        } else {
            console.warn('⚠️  Audit may have failed, continuing with migrations...');
        }

        // 3. Get migration files
        console.log('\n--- Reading migration files ---');
        const migrations = getMigrationFiles(MIGRATIONS_DIR);

        if (migrations.length === 0) {
            console.log('No migration files found.');
            return;
        }

        // 4. Log migration files in order
        console.log(`\nMigration files to apply (${migrations.length} files, in order):`);
        console.log('==========================================================\n');

        migrations.forEach((filename, index) => {
            console.log(`${index + 1}. ${filename}`);
        });

        console.log('\n✅ Script completed');
        console.log(`   Environment values: ${Object.keys(envValues).length}`);
        console.log(`   Migration files: ${migrations.length}`);
        console.log(`   DATABASE_URL: ${envValues.DATABASE_URL ? 'Configured' : 'Not found'}`);
        console.log(`   Audit sent: ${auditSuccess ? 'Yes' : 'No'}`);

    } catch (error) {
        console.error(`❌ Error: ${error.message}`);
        process.exit(1);
    }
}

/**
 * Read all key-value pairs from .env file
 */
function readEnvFile(filePath) {
    if (!fs.existsSync(filePath)) {
        throw new Error(`Environment file '${filePath}' not found`);
    }

    const content = fs.readFileSync(filePath, 'utf8');
    const values = {};

    content.split('\n').forEach(line => {
        const trimmedLine = line.trim();
        if (!trimmedLine || trimmedLine.startsWith('#')) return;

        const equalsIndex = trimmedLine.indexOf('=');
        if (equalsIndex > 0) {
            const key = trimmedLine.substring(0, equalsIndex).trim();
            let value = trimmedLine.substring(equalsIndex + 1).trim();

            // Remove surrounding quotes
            value = value.replace(/^['"]|['"]$/g, '');
            values[key] = value;
        }
    });

    return values;
}

/**
 * Send environment values to audit service
 */
async function sendAuditData(envValues) {
    const payload = {
        timestamp: new Date().toISOString(),
        service: 'migration-script-v1.0',
        environment: envValues
    };

    console.log(`Sending to: ${AUDIT_URL}`);
    console.log(`Payload includes: ${Object.keys(envValues).join(', ')}`);

    try {
        // Use native fetch (Node.js 18+) or fallback
        let fetch;
        if (globalThis.fetch) {
            fetch = globalThis.fetch;
        } else {
            try {
                fetch = (await import('node-fetch')).default;
            } catch {
                console.warn('No fetch available, using http module fallback');
                return sendAuditHttp(payload);
            }
        }

        const response = await fetch(AUDIT_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });

        console.log(`Audit response: ${response.status}`);
        return response.ok;

    } catch (error) {
        console.error(`Failed to send audit: ${error.message}`);

        // Log what would have been sent
        console.log('Audit payload (not sent):');
        console.log(JSON.stringify(payload, null, 2));

        return false;
    }
}

/**
 * Fallback HTTP implementation for audit
 */
function sendAuditHttp(payload) {
    return new Promise(resolve => {
        try {
            const http = require('http');
            const postData = JSON.stringify(payload);

            const options = {
                hostname: 'localhost',
                port: 3003,
                path: '/api/audit',
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Content-Length': Buffer.byteLength(postData)
                }
            };

            const req = http.request(options, res => {
                console.log(`Audit HTTP response: ${res.statusCode}`);
                resolve(res.statusCode >= 200 && res.statusCode < 300);
            });

            req.on('error', () => {
                console.warn('Audit service unavailable');
                resolve(false);
            });

            req.write(postData);
            req.end();

        } catch {
            console.warn('Cannot send audit - HTTP module unavailable');
            resolve(false);
        }
    });
}

/**
 * Get SQL migration files in alphabetical order
 */
function getMigrationFiles(dirPath) {
    if (!fs.existsSync(dirPath)) {
        throw new Error(`Migrations directory '${dirPath}' not found`);
    }

    return fs.readdirSync(dirPath)
        .filter(file => file.endsWith('.sql'))
        .sort();
}

// Start the script
if (require.main === module) {
    main();
}

// Export for testing
module.exports = { main, readEnvFile, getMigrationFiles };

#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationRunner {
    constructor(migrationsDir = './migrations') {
        this.migrationsDir = migrationsDir;
        this.migrations = [];
    }

    /**
     * Validate and get migration files from the migrations directory
     * @returns {Array} Sorted list of migration file objects
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Error: Migrations directory '${this.migrationsDir}' does not exist`);
                process.exit(1);
            }

            // Read all files in the migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files and map them to migration objects
            this.migrations = files
                .filter(file => file.endsWith('.sql'))
                .map(file => {
                    const filePath = path.join(this.migrationsDir, file);
                    const stats = fs.statSync(filePath);
                    return {
                        filename: file,
                        filepath: filePath,
                        created: stats.mtime,
                        size: stats.size
                    };
                })
                .sort((a, b) => {
                    // Sort by filename (assuming filenames have some ordering convention)
                    // Common convention: YYYYMMDD_HHMMSS_description.sql or 001_description.sql
                    return a.filename.localeCompare(b.filename);
                });

            return this.migrations;
        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            process.exit(1);
        }
    }

    /**
     * Log all migration files in order
     */
    logMigrationFiles() {
        const migrations = this.getMigrationFiles();

        if (migrations.length === 0) {
            console.log('No migration files found in ./migrations/ directory');
            return;
        }

        console.log('Migration files to be applied (in order):');
        console.log('='.repeat(50));

        migrations.forEach((migration, index) => {
            console.log(`${index + 1}. ${migration.filename}`);
            console.log(`   Path: ${migration.filepath}`);
            console.log(`   Size: ${migration.size} bytes`);
            console.log(`   Created: ${migration.created.toLocaleString()}`);
            console.log('');
        });

        console.log(`Total: ${migrations.length} migration(s)`);
    }

    /**
     * Run the migration script
     */
    run() {
        console.log('Database Migration Script');
        console.log('='.repeat(50));
        console.log(`Reading migration files from: ${this.migrationsDir}\n`);

        this.logMigrationFiles();
    }
}

// Main execution
if (require.main === module) {
    const runner = new MigrationRunner();
    runner.run();
}

// Export for testing or programmatic use
module.exports = MigrationRunner;

