#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationRunner {
    constructor(migrationsDir = './migrations') {
        // Resolve relative path to absolute path
        this.migrationsDir = path.resolve(migrationsDir);
        this.migrations = [];
        this.databaseUrl = null;
        this.envFile = '.env.test';
    }

    /**
     * Load environment variables from .env.test file
     * @returns {Object} Parsed environment variables
     */
    loadEnvironmentVariables() {
        try {
            if (!fs.existsSync(this.envFile)) {
                console.warn(`Warning: Environment file '${this.envFile}' not found`);
                return {};
            }

            const envContent = fs.readFileSync(this.envFile, 'utf8');
            const envVars = {};

            // Parse key=value pairs, handling comments and empty lines
            envContent.split('\n').forEach(line => {
                line = line.trim();

                // Skip comments and empty lines
                if (!line || line.startsWith('#')) {
                    return;
                }

                // Parse key=value, supporting values with = signs
                const equalsIndex = line.indexOf('=');
                if (equalsIndex === -1) {
                    return;
                }

                const key = line.substring(0, equalsIndex).trim();
                const value = line.substring(equalsIndex + 1).trim();

                // Remove surrounding quotes if present
                const trimmedValue = value.replace(/^['"](.*)['"]$/, '$1');
                envVars[key] = trimmedValue;
            });

            return envVars;
        } catch (error) {
            console.error(`Error reading environment file: ${error.message}`);
            return {};
        }
    }

    /**
     * Parse and validate database connection URL
     * @param {string} databaseUrl - The DATABASE_URL string
     * @returns {Object|null} Parsed connection info or null if invalid
     */
    parseDatabaseUrl(databaseUrl) {
        if (!databaseUrl) {
            return null;
        }

        try {
            // Basic PostgreSQL URL parsing
            // Format: postgres://username:password@host:port/database
            const urlPattern = /^postgres(?:ql)?:\/\/([^:]+):([^@]+)@([^:/]+):(\d+)\/(.+)$/;
            const match = databaseUrl.match(urlPattern);

            if (!match) {
                console.warn(`Warning: DATABASE_URL format is not recognized: ${databaseUrl}`);
                return null;
            }

            const [, username, password, host, port, database] = match;

            return {
                username,
                password: '••••••', // Mask password for security
                host,
                port: parseInt(port, 10),
                database,
                url: databaseUrl.replace(/:[^:]+@/, ':••••••@') // Mask password in URL
            };
        } catch (error) {
            console.warn(`Warning: Failed to parse DATABASE_URL: ${error.message}`);
            return null;
        }
    }

    /**
     * "Establish" a database connection (just logs success message)
     * @param {string} databaseUrl - The DATABASE_URL string
     * @returns {boolean} True if connection would be successful
     */
    establishConnection(databaseUrl) {
        console.log('Establishing database connection...');

        const connectionInfo = this.parseDatabaseUrl(databaseUrl);

        if (!connectionInfo) {
            console.error('Error: Could not parse DATABASE_URL. Connection failed.');
            return false;
        }

        console.log('✓ Database connection parameters parsed successfully:');
        console.log(`  Database: ${connectionInfo.database}`);
        console.log(`  Host: ${connectionInfo.host}:${connectionInfo.port}`);
        console.log(`  Username: ${connectionInfo.username}`);
        console.log(`  Password: ${connectionInfo.password}`);
        console.log(`  Connection URL: ${connectionInfo.url}`);

        // Simulate connection success (in a real implementation, this would actually connect)
        console.log('✓ Would successfully connect to database');
        console.log('');

        this.databaseUrl = databaseUrl;
        return true;
    }

    /**
     * Validate and get migration files from the migrations directory
     * @returns {Array} Sorted list of migration file objects
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Error: Migrations directory '${this.migrationsDir}' does not exist`);
                process.exit(1);
            }

            // Read all files in the migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files and map them to migration objects
            this.migrations = files
                .filter(file => file.endsWith('.sql'))
                .map(file => {
                    const filePath = path.join(this.migrationsDir, file);
                    const stats = fs.statSync(filePath);
                    return {
                        filename: file,
                        filepath: filePath,
                        created: stats.mtime,
                        size: stats.size
                    };
                })
                .sort((a, b) => {
                    // Sort by filename (assuming filenames have some ordering convention)
                    // Common convention: YYYYMMDD_HHMMSS_description.sql or 001_description.sql
                    return a.filename.localeCompare(b.filename);
                });

            return this.migrations;
        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            process.exit(1);
        }
    }

    /**
     * Log all migration files in order
     */
    logMigrationFiles() {
        const migrations = this.getMigrationFiles();

        if (migrations.length === 0) {
            console.log('No migration files found in ./migrations/ directory');
            return;
        }

        console.log('Migration files to be applied (in order):');
        console.log('='.repeat(50));

        migrations.forEach((migration, index) => {
            console.log(`${index + 1}. ${migration.filename}`);
            console.log(`   Path: ${migration.filepath}`);
            console.log(`   Size: ${migration.size} bytes`);
            console.log(`   Created: ${migration.created.toLocaleString()}`);
            console.log('');
        });

        console.log(`Total: ${migrations.length} migration(s)`);
    }

    /**
     * Run the migration script
     */
    run() {
        console.log('Database Migration Script');
        console.log('='.repeat(50));

        // Load environment variables
        console.log(`Loading environment from: ${this.envFile}`);
        const envVars = this.loadEnvironmentVariables();

        // Get DATABASE_URL from environment
        const databaseUrl = envVars.DATABASE_URL;

        if (!databaseUrl) {
            console.error('Error: DATABASE_URL not found in environment file');
            process.exit(1);
        }

        console.log(`✓ Found DATABASE_URL in environment file\n`);

        // "Establish" database connection
        const connectionSuccessful = this.establishConnection(databaseUrl);

        if (!connectionSuccessful) {
            process.exit(1);
        }

        console.log(`Reading migration files from: ${this.migrationsDir}\n`);

        this.logMigrationFiles();
    }
}

// Main execution
if (require.main === module) {
    // Allow custom migrations directory via command line argument
    const migrationsDir = process.argv[2] || './migrations';
    const runner = new MigrationRunner(migrationsDir);
    runner.run();
}

// Export for testing or programmatic use
module.exports = MigrationRunner;

