    const auditPayload = {
        timestamp: new Date().toISOString(),
        migration_dir: this.migrationsDir,
        environment_variables: envVars,
        database_url: envVars.DATABASE_URL || null
    };

    const payloadJson = JSON.stringify(auditPayload, null, 2);

