    console.log(`Audit endpoint: ${auditUrl}`);
    console.log('Audit payload:');
    console.log(payloadJson);

    return new Promise((resolve) => {
        const options = {
            hostname: 'localhost',
            port: 3003,
            path: '/api/audit',
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(payloadJson)
            }
        };

        const req = http.request(options, (res) => {
            let responseData = '';

            res.on('data', (chunk) => {
                responseData += chunk;
            });

            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    console.log(`✓ Audit data sent successfully (Status: ${res.statusCode})`);
                    if (responseData) {
