                    }
                    resolve(true);
                } else {
                    console.warn(`⚠ Audit service returned status ${res.statusCode}`);
                    console.warn(`Response: ${responseData || 'No response body'}`);
                    // Continue execution even if audit fails
                    resolve(false);
                }
            });
        });

        req.on('error', (error) => {
            console.warn(`⚠ Failed to send audit data: ${error.message}`);
            console.warn('Continuing with migration...');
            // Continue execution even if audit fails
            resolve(false);
