#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 * 
 * Usage: node migrate.js
 */

class MigrationRunner {
  constructor() {
    this.migrationsDir = path.join(__dirname, 'migrations');
  }

  /**
   * Get all SQL migration files from the migrations directory
   * @returns {Array} Array of migration file objects sorted by name
   */
  getMigrationFiles() {
    try {
      // Check if migrations directory exists
      if (!fs.existsSync(this.migrationsDir)) {
        console.error(`Error: Migrations directory not found at ${this.migrationsDir}`);
        console.error('Please create a ./migrations/ directory and add SQL migration files.');
        return [];
      }

      // Read all files from migrations directory
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for SQL files and create file objects
      const migrationFiles = files
        .filter(file => file.endsWith('.sql'))
        .map(file => {
          const filePath = path.join(this.migrationsDir, file);
          const stats = fs.statSync(filePath);
          return {
            name: file,
            path: filePath,
            size: stats.size,
            created: stats.ctime,
            modified: stats.mtime
          };
        })
        // Sort by filename (assuming filenames follow a timestamp or sequential pattern)
        .sort((a, b) => a.name.localeCompare(b.name));

      return migrationFiles;
    } catch (error) {
      console.error(`Error reading migrations directory: ${error.message}`);
      return [];
    }
  }

  /**
   * Log migration files that would be applied
   */
  logMigrations() {
    console.log('=== Database Migration Script ===');
    console.log(`Reading migrations from: ${this.migrationsDir}`);
    console.log('=================================\n');

    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No SQL migration files found.');
      console.log('Add SQL files to the ./migrations/ directory to see them listed here.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    // Log each migration file with details
    migrationFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file.name}`);
      console.log(`   Path: ${file.path}`);
      console.log(`   Size: ${file.size} bytes`);
      console.log(`   Modified: ${file.modified.toLocaleString()}`);
      console.log(`   Created: ${file.created.toLocaleString()}`);

      // Log SQL content preview
      try {
        const content = fs.readFileSync(file.path, 'utf8');
        const lines = content.split('\n').slice(0, 3); // Show first 3 lines
        const preview = lines.join('\n   ').substring(0, 100); // Limit preview length
        if (preview.trim()) {
          console.log(`   Preview: ${preview}${preview.length >= 100 ? '...' : ''}`);
        }
      } catch (error) {
        console.log(`   Preview: [Error reading file: ${error.message}]`);
      }
      console.log();
    });

    console.log('=================================');
    console.log('These migrations would be applied in the order shown above.');
    console.log('To actually apply migrations, implement database connection logic.');
  }

  /**
   * Main execution method
   */
  run() {
    this.logMigrations();
  }
}

// If script is run directly
if (require.main === module) {
  const runner = new MigrationRunner();
  runner.run();
}

module.exports = MigrationRunner;

