    this.databaseUrl = null;
  }

  /**
   * Read DATABASE_URL from .env.test file
   * @returns {string|null} Database URL or null if not found
   */
  readDatabaseUrl() {
    try {
      if (!fs.existsSync(this.envFile)) {
        console.error(`Error: Environment file not found at ${this.envFile}`);
        return null;
      }

      const envContent = fs.readFileSync(this.envFile, 'utf8');
      const lines = envContent.split('\n');

      for (const line of lines) {
        // Skip comments and empty lines
        const trimmedLine = line.trim();
        if (!trimmedLine || trimmedLine.startsWith('#')) {
          continue;
        }

        // Look for DATABASE_URL
        if (trimmedLine.startsWith('DATABASE_URL=')) {
          // Extract the value after the equals sign
          const url = trimmedLine.substring('DATABASE_URL='.length).trim();

          // Remove quotes if present
          const cleanUrl = url.replace(/^['"]|['"]$/g, '');
          return cleanUrl;
        }
      }

      console.error('Error: DATABASE_URL not found in .env.test file');
      return null;
    } catch (error) {
      console.error(`Error reading environment file: ${error.message}`);
      return null;
    }
  }

  /**
   * Parse database URL and extract connection details
   * @param {string} url - Database connection URL
   * @returns {object} Parsed connection details
   */
  parseDatabaseUrl(url) {
    try {
      // Parse the PostgreSQL URL format: postgres://user:pass@host:port/database
      const urlPattern = /^([^:]+):\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
      const match = url.match(urlPattern);

      if (!match) {
        // Try alternative format without port
        const altPattern = /^([^:]+):\/\/([^:]+):([^@]+)@([^/]+)\/(.+)$/;
        const altMatch = url.match(altPattern);

        if (!altMatch) {
          return {
            protocol: 'unknown',
            host: 'unknown',
            port: 'unknown',
            database: 'unknown',
            user: 'unknown',
            hasPassword: false
          };
        }

        return {
          protocol: altMatch[1],
          user: altMatch[2],
          hasPassword: true,
          host: altMatch[4],
          port: 'default',
          database: altMatch[5]
        };
      }

      return {
        protocol: match[1],
        user: match[2],
        hasPassword: true,
        host: match[4],
        port: match[5],
        database: match[6]
      };
    } catch (error) {
      console.error(`Error parsing database URL: ${error.message}`);
      return {
        protocol: 'unknown',
        host: 'unknown',
        port: 'unknown',
        database: 'unknown',
        user: 'unknown',
        hasPassword: false
      };
    }
  }

  /**
   * Log database connection information
   */
  logDatabaseConnection() {
    console.log('=== Database Connection Setup ===');

    this.databaseUrl = this.readDatabaseUrl();

