      console.log('No database connection URL found.');
      console.log('Please add DATABASE_URL to .env.test file.');
      console.log('=================================\n');
      return false;
    }

    // Parse the database URL
    const dbInfo = this.parseDatabaseUrl(this.databaseUrl);

