#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 * 
 * Usage: node migrate.js
 */

class MigrationRunner {
  constructor() {
    this.migrationsDir = path.join(__dirname, 'migrations');
    this.envFile = path.join(__dirname, '.env.test');
    this.databaseUrl = null;
  }

  /**
   * Read DATABASE_URL from .env.test file
   * @returns {string|null} Database URL or null if not found
   */
  readDatabaseUrl() {
    try {
      if (!fs.existsSync(this.envFile)) {
        console.error(`Error: Environment file not found at ${this.envFile}`);
        return null;
      }

      const envContent = fs.readFileSync(this.envFile, 'utf8');
      const lines = envContent.split('\n');

      for (const line of lines) {
        // Skip comments and empty lines
        const trimmedLine = line.trim();
        if (!trimmedLine || trimmedLine.startsWith('#')) {
          continue;
        }

        // Look for DATABASE_URL
        if (trimmedLine.startsWith('DATABASE_URL=')) {
          // Extract the value after the equals sign
          const url = trimmedLine.substring('DATABASE_URL='.length).trim();

          // Remove quotes if present
          const cleanUrl = url.replace(/^['"]|['"]$/g, '');
          return cleanUrl;
        }
      }

      console.error('Error: DATABASE_URL not found in .env.test file');
      return null;
    } catch (error) {
      console.error(`Error reading environment file: ${error.message}`);
      return null;
    }
  }

  /**
   * Parse database URL and extract connection details
   * @param {string} url - Database connection URL
   * @returns {object} Parsed connection details
   */
  parseDatabaseUrl(url) {
    try {
      // Parse the PostgreSQL URL format: postgres://user:pass@host:port/database
      const urlPattern = /^([^:]+):\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
      const match = url.match(urlPattern);

      if (!match) {
        // Try alternative format without port
        const altPattern = /^([^:]+):\/\/([^:]+):([^@]+)@([^/]+)\/(.+)$/;
        const altMatch = url.match(altPattern);

        if (!altMatch) {
          return {
            protocol: 'unknown',
            host: 'unknown',
            port: 'unknown',
            database: 'unknown',
            user: 'unknown',
            hasPassword: false
          };
        }

        return {
          protocol: altMatch[1],
          user: altMatch[2],
          hasPassword: true,
          host: altMatch[4],
          port: 'default',
          database: altMatch[5]
        };
      }

      return {
        protocol: match[1],
        user: match[2],
        hasPassword: true,
        host: match[4],
        port: match[5],
        database: match[6]
      };
    } catch (error) {
      console.error(`Error parsing database URL: ${error.message}`);
      return {
        protocol: 'unknown',
        host: 'unknown',
        port: 'unknown',
        database: 'unknown',
        user: 'unknown',
        hasPassword: false
      };
    }
  }

  /**
   * Log database connection information
   */
  logDatabaseConnection() {
    console.log('=== Database Connection Setup ===');

    this.databaseUrl = this.readDatabaseUrl();

    if (!this.databaseUrl) {
      console.log('No database connection URL found.');
      console.log('Please add DATABASE_URL to .env.test file.');
      console.log('=================================\n');
      return false;
    }

    // Parse the database URL
    const dbInfo = this.parseDatabaseUrl(this.databaseUrl);

    // Log connection details (masking sensitive information)
    console.log(`✓ Successfully read DATABASE_URL from ${this.envFile}`);
    console.log(`  Protocol: ${dbInfo.protocol}`);
    console.log(`  Host: ${dbInfo.host}`);
    console.log(`  Port: ${dbInfo.port}`);
    console.log(`  Database: ${dbInfo.database}`);
    console.log(`  User: ${dbInfo.user}`);
    console.log(`  Password: ${dbInfo.hasPassword ? '*** (masked)' : 'none'}`);

    // Show a safe preview of the URL (mask password)
    const maskedUrl = this.databaseUrl.replace(/:([^:]+)@/, ':***@');
    console.log(`  Connection URL: ${maskedUrl}`);

    console.log('\n⚠️  Note: Database connection is simulated for logging purposes only.');
    console.log('   No actual database connection will be made.');
    console.log('=================================\n');

    return true;
  }

  /**
   * Get all SQL migration files from the migrations directory
   * @returns {Array} Array of migration file objects sorted by name
   */
  getMigrationFiles() {
    try {
      // Check if migrations directory exists
      if (!fs.existsSync(this.migrationsDir)) {
        console.error(`Error: Migrations directory not found at ${this.migrationsDir}`);
        console.error('Please create a ./migrations/ directory and add SQL migration files.');
        return [];
      }

      // Read all files from migrations directory
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for SQL files and create file objects
      const migrationFiles = files
        .filter(file => file.endsWith('.sql'))
        .map(file => {
          const filePath = path.join(this.migrationsDir, file);
          const stats = fs.statSync(filePath);
          return {
            name: file,
            path: filePath,
            size: stats.size,
            created: stats.ctime,
            modified: stats.mtime
          };
        })
        // Sort by filename (assuming filenames follow a timestamp or sequential pattern)
        .sort((a, b) => a.name.localeCompare(b.name));

      return migrationFiles;
    } catch (error) {
      console.error(`Error reading migrations directory: ${error.message}`);
      return [];
    }
  }

  /**
   * Log migration files that would be applied
   */
  logMigrations() {
    console.log('=== Database Migration Script ===');

    // First, try to read and log database connection
    const hasConnection = this.logDatabaseConnection();

    if (!hasConnection) {
      console.log('Continuing with migration file listing only...\n');
    }

    console.log(`Reading migrations from: ${this.migrationsDir}`);
    console.log('=================================\n');

    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No SQL migration files found.');
      console.log('Add SQL files to the ./migrations/ directory to see them listed here.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    // Log each migration file with details
    migrationFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file.name}`);
      console.log(`   Path: ${file.path}`);
      console.log(`   Size: ${file.size} bytes`);
      console.log(`   Modified: ${file.modified.toLocaleString()}`);
      console.log(`   Created: ${file.created.toLocaleString()}`);

      // Log SQL content preview
      try {
        const content = fs.readFileSync(file.path, 'utf8');
        const lines = content.split('\n').slice(0, 3); // Show first 3 lines
        const preview = lines.join('\n   ').substring(0, 100); // Limit preview length
        if (preview.trim()) {
          console.log(`   Preview: ${preview}${preview.length >= 100 ? '...' : ''}`);
        }
      } catch (error) {
        console.log(`   Preview: [Error reading file: ${error.message}]`);
      }
      console.log();
    });

    console.log('=================================');
    console.log('These migrations would be applied in the order shown above.');
    if (this.databaseUrl) {
      const dbInfo = this.parseDatabaseUrl(this.databaseUrl);
      console.log(`If executed, migrations would run on: ${dbInfo.database}@${dbInfo.host}:${dbInfo.port}`);
    } else {
      console.log('No database connection configured.');
    }
    console.log('To actually apply migrations, implement database connection logic.');
  }

  /**
   * Main execution method
   */
  run() {
    this.logMigrations();
  }
}

// If script is run directly
if (require.main === module) {
  const runner = new MigrationRunner();
  runner.run();
}

module.exports = MigrationRunner;

