/**
 * Send audit data to migration audit service
 * @param {object} envVars - All environment variables from .env.test
 * @returns {Promise<boolean>} True if audit was successful
 */
async sendAuditData(envVars) {
  const auditUrl = 'http://localhost:3003/api/audit';

  // Prepare audit data
  const auditData = {
    timestamp: new Date().toISOString(),
    script: 'migrate.js',
    action: 'migration_preview',
    environment_variables: envVars,
    metadata: {
      migrations_dir: this.migrationsDir,
      env_file: this.envFile
    }
  };

  const data = JSON.stringify(auditData);

  console.log('=== Migration Audit Service ===');
  console.log(`Sending audit data to: ${auditUrl}`);
  console.log('Audit payload preview:');
  console.log(JSON.stringify({
    ...auditData,
    environment_variables: Object.keys(auditData.environment_variables).reduce((acc, key) => {
      // Mask sensitive values for logging
      if (key.toLowerCase().includes('key') || 
          key.toLowerCase().includes('secret') || 
          key.toLowerCase().includes('password') ||
          key.toLowerCase().includes('token')) {
        acc[key] = '*** (masked)';
      } else if (key === 'DATABASE_URL') {
        acc[key] = auditData.environment_variables[key].replace(/:([^:]+)@/, ':***@');
      } else {
        acc[key] = auditData.environment_variables[key];
      }
      return acc;
    }, {})
  }, null, 2));

  return new Promise((resolve) => {
    const url = new URL(auditUrl);
    const options = {
      hostname: url.hostname,
      port: url.port || 3003,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data),
        'User-Agent': 'MigrationAudit/1.0'
      },
      timeout: 10000 // 10 second timeout
    };

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        console.log(`Audit service response: ${res.statusCode} ${res.statusMessage}`);

        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('✓ Audit data successfully sent to compliance service\n');
          resolve(true);
        } else {
          console.error(`✗ Audit service returned error status: ${res.statusCode}`);
          console.error(`Response: ${responseData}`);
          console.log('Continuing with migration logging despite audit failure...\n');
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.error(`✗ Failed to send audit data: ${error.message}`);
      console.log('Continuing with migration logging despite audit failure...\n');
      resolve(false);
    });

    req.on('timeout', () => {
      console.error('✗ Audit request timed out after 10 seconds');
      req.destroy();
      console.log('Continuing with migration logging despite audit failure...\n');
      resolve(false);
    });

    req.write(data);
    req.end();
  });
}

