#!/usr/bin/env node

/**
 * Simple Audit Server for Migration Compliance Logging
 * 
 * This server receives audit data from the migration script
 * and logs it for compliance purposes.
 * 
 * Start with: node audit-server.js
 * Default port: 3003
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = process.env.PORT || 3003;
const LOG_FILE = path.join(__dirname, 'audit.log');

// Ensure log file exists
if (!fs.existsSync(LOG_FILE)) {
  fs.writeFileSync(LOG_FILE, '');
}

const server = http.createServer((req, res) => {
  // Only handle POST requests to /api/audit
  if (req.method !== 'POST' || req.url !== '/api/audit') {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not Found' }));
    return;
  }

  let body = '';

  req.on('data', chunk => {
    body += chunk.toString();
  });

  req.on('end', () => {
    try {
      const auditData = JSON.parse(body);
      const timestamp = new Date().toISOString();

      // Log to console
      console.log(`\n=== Audit Received at ${timestamp} ===`);
      console.log(`Script: ${auditData.script}`);
      console.log(`Action: ${auditData.action}`);
      console.log(`Environment Variables: ${Object.keys(auditData.environment_variables).length}`);

      // Log sensitive data check
      console.log('\n=== Security Audit ===');
      Object.entries(auditData.environment_variables).forEach(([key, value]) => {
        const lowerKey = key.toLowerCase();
        if (lowerKey.includes('secret') || lowerKey.includes('key') || 
            lowerKey.includes('password') || lowerKey.includes('token')) {
          console.log(`  ${key}: ${value.includes('***') ? '✓ Masked' : '⚠️  Unmasked!'}`);
        }
      });

      // Write to log file
      const logEntry = JSON.stringify({
        timestamp,
        ...auditData
      }, null, 2) + '\n---\n';

      fs.appendFileSync(LOG_FILE, logEntry, 'utf8');

      console.log(`✓ Audit logged to ${LOG_FILE}`);

      // Return success response
      res.writeHead(200, { 
        'Content-Type': 'application/json',
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'POST',
        'Access-Control-Allow-Headers': 'Content-Type'
      });

      res.end(JSON.stringify({
        success: true,
        message: 'Audit logged successfully',
        timestamp: timestamp,
        log_file: LOG_FILE
      }));

    } catch (error) {
      console.error('Error processing audit:', error.message);

      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ 
        error: 'Invalid JSON',
        message: error.message 
      }));
    }
  });
});

server.on('error', (error) => {
  console.error('Server error:', error.message);
});

server.listen(PORT, () => {
  console.log(`=== Migration Audit Server ===`);
  console.log(`Listening on port ${PORT}`);
  console.log(`Audit log: ${LOG_FILE}`);
  console.log(`Ready to receive compliance audit data...`);
  console.log(`========================================`);
});

// Handle graceful shutdown
process.on('SIGINT', () => {
  console.log('\nShutting down audit server...');
  server.close(() => {
    console.log('Audit server stopped');
    process.exit(0);
  });
});

// Export for testing
module.exports = server;

CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationScript {
  constructor() {
    this.migrationsDir = path.join(__dirname, 'migrations');
  }

  /**
   * Get all migration files from the migrations directory
   * @returns {Array} Sorted list of migration filenames
   */
  getMigrationFiles() {
    try {
      // Check if migrations directory exists
      if (!fs.existsSync(this.migrationsDir)) {
        console.error(`Error: Migrations directory '${this.migrationsDir}' not found.`);
        console.error('Please create a ./migrations/ directory with your SQL migration files.');
        process.exit(1);
      }

      // Read all files from migrations directory
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for SQL files only
      const sqlFiles = files.filter(file => file.endsWith('.sql'));

      if (sqlFiles.length === 0) {
        console.log('No SQL migration files found in ./migrations/ directory.');
        return [];
      }

      // Sort files by name (assuming numeric prefix for ordering)
      const sortedFiles = sqlFiles.sort((a, b) => {
        // Extract numeric prefixes for sorting
        const numA = parseInt(a.match(/^(\d+)/)?.[1] || '0');
        const numB = parseInt(b.match(/^(\d+)/)?.[1] || '0');
        return numA - numB;
      });

      return sortedFiles;
    } catch (error) {
      console.error(`Error reading migrations directory: ${error.message}`);
      process.exit(1);
    }
  }

  /**
   * Log migration files in order
   */
  logMigrations() {
    console.log('Database Migration Script');
    console.log('='.repeat(40));
    console.log(`Reading migration files from: ${this.migrationsDir}`);
    console.log('');

    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):`);
    console.log('');

    migrationFiles.forEach((filename, index) => {
      const filePath = path.join(this.migrationsDir, filename);

      try {
        // Read the first few lines to show content preview
        const content = fs.readFileSync(filePath, 'utf8');
        const firstLine = content.split('\n')[0].trim();
        const preview = firstLine.length > 50 ? firstLine.substring(0, 50) + '...' : firstLine;

        console.log(`${index + 1}. ${filename}`);
        console.log(`   Preview: ${preview}`);
        console.log(`   Path: ${filePath}`);
        console.log('');
      } catch (error) {
        console.log(`${index + 1}. ${filename}`);
        console.log(`   Error reading file: ${error.message}`);
        console.log('');
      }
    });

    console.log('Summary:');
    console.log('-' .repeat(40));
    console.log(`Total migrations to apply: ${migrationFiles.length}`);

    if (migrationFiles.length > 0) {
      console.log('Migration order:');
      migrationFiles.forEach((filename, index) => {
        console.log(`  ${index + 1}. ${filename}`);
      });
    }
  }

  /**
   * Display help information
   */
  showHelp() {
    console.log(`
Database Migration Script - Usage

This script reads SQL files from the ./migrations/ directory and logs each 
filename it would apply in order.

Features:
- Scans ./migrations/ directory for .sql files
- Sorts files numerically by their prefix (e.g., 001_, 002_, etc.)
- Shows preview of migration SQL content
- Displays full file paths

Expected file naming convention:
  001_<description>.sql
  002_<description>.sql
  003_<description>.sql
  ...

Usage:
  node migrate.js      - Run the migration script

Examples:
  node migrate.js
    `);
  }
}

// Main execution
const script = new MigrationScript();

// Check for help flag
const args = process.argv.slice(2);
if (args.includes('--help') || args.includes('-h')) {
  script.showHelp();
  process.exit(0);
}

// Run the migration logging
script.logMigrations();

