 */

class MigrationScript {
  constructor() {
    this.migrationsDir = path.join(__dirname, 'migrations');
    this.envFile = path.join(__dirname, '.env.test');
    this.databaseUrl = null;
  }

  /**
   * Read DATABASE_URL from .env.test file
   * @returns {string|null} The database URL or null if not found
   */
  readDatabaseUrl() {
    try {
      if (!fs.existsSync(this.envFile)) {
        console.warn(`Warning: Environment file '${this.envFile}' not found.`);
        return null;
      }

      const envContent = fs.readFileSync(this.envFile, 'utf8');
      const lines = envContent.split('\n');

      for (const line of lines) {
        // Skip comments and empty lines
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith('#')) continue;

        // Check for DATABASE_URL
        if (trimmed.startsWith('DATABASE_URL=')) {
          const url = trimmed.substring('DATABASE_URL='.length).trim();

          // Remove quotes if present
          if ((url.startsWith('"') && url.endsWith('"')) || 
              (url.startsWith("'") && url.endsWith("'"))) {
            return url.substring(1, url.length - 1);
          }

          return url;
        }
      }

      console.warn('Warning: DATABASE_URL not found in .env.test');
      return null;
    } catch (error) {
      console.error(`Error reading .env.test file: ${error.message}`);
      return null;
    }
  }

  /**
   * Simulate database connection and log success message
   */
  logConnectionStatus() {
    this.databaseUrl = this.readDatabaseUrl();

    if (this.databaseUrl) {
      // Extract database type from URL for nicer logging
      let dbType = 'database';
      if (this.databaseUrl.startsWith('postgres://')) {
        dbType = 'PostgreSQL';
      } else if (this.databaseUrl.startsWith('mysql://')) {
        dbType = 'MySQL';
      } else if (this.databaseUrl.startsWith('mongodb://')) {
        dbType = 'MongoDB';
      }

      // Extract host/port info for logging (mask password for security)
      const maskedUrl = this.maskPasswordInUrl(this.databaseUrl);

      console.log(`✓ Connected to ${dbType} successfully`);
      console.log(`  Connection URL: ${maskedUrl}`);
    } else {
      console.log('⚠ No DATABASE_URL found in .env.test - running in dry mode');
    }

    console.log('');
  }

  /**
   * Mask password in database URL for secure logging
   * @param {string} url - The database URL
   * @returns {string} URL with password masked
   */
  maskPasswordInUrl(url) {
    try {
      // Simple password masking for logging
      const urlPattern = /^(postgres|mysql|mongodb):\/\/([^:]+):([^@]+)@(.+)$/;
      const match = url.match(urlPattern);

      if (match) {
        const [, protocol, username, password, rest] = match;
        return `${protocol}://${username}:*****@${rest}`;
      }

      return url; // Return as-is if pattern doesn't match
    } catch {
      return url; // Return as-is on any error
    }
  }

