#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const https = require('https');
const http = require('http');

/**
 * Simple Database Migration Script
 * 
 * Reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 * Reads all values from .env.test and sends them to 
 * http://localhost:3003/api/audit for compliance logging.
 */

const migrationsDir = path.join(__dirname, 'migrations');
const envFile = path.join(__dirname, '.env.test');
const auditServiceUrl = 'http://localhost:3003/api/audit';

console.log('Simple Migration Script');
console.log('='.repeat(40));

// Function to read all values from .env.test
function readEnvFile() {
  const envValues = {};

  try {
    if (!fs.existsSync(envFile)) {
      console.warn(`Warning: Environment file '${envFile}' not found.`);
      return envValues;
    }

    const envContent = fs.readFileSync(envFile, 'utf8');
    const lines = envContent.split('\n');

    for (const line of lines) {
      // Skip comments and empty lines
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) continue;

      // Parse key=value pairs
      const equalsIndex = trimmed.indexOf('=');
      if (equalsIndex === -1) continue;

      const key = trimmed.substring(0, equalsIndex).trim();
      let value = trimmed.substring(equalsIndex + 1).trim();

      // Remove quotes if present
      if ((value.startsWith('"') && value.endsWith('"')) || 
          (value.startsWith("'") && value.endsWith("'"))) {
        value = value.substring(1, value.length - 1);
      }

      envValues[key] = value;
    }

    console.log(`Read ${Object.keys(envValues).length} values from .env.test`);
    return envValues;
  } catch (error) {
    console.error(`Error reading .env.test file: ${error.message}`);
    return envValues;
  }
}

// Function to mask password in URL for secure logging
function maskPasswordInUrl(url) {
  try {
    // Simple password masking for logging
    return url.replace(/:([^:@]+)@/, ':*****@');
  } catch {
    return url; // Return as-is on any error
  }
}

// Function to send audit data to compliance service
async function sendAuditData(envValues) {
  console.log('\nSending audit data to compliance service...');

  if (Object.keys(envValues).length === 0) {
    console.log('⚠ No environment data to audit');
    return false;
  }

  return new Promise((resolve) => {
    const auditData = {
      timestamp: new Date().toISOString(),
      service: 'database-migration',
      environment: 'test',
      values: envValues
    };

    // Log what we're sending (with masked sensitive data)
    const maskedData = { ...auditData };
    Object.keys(maskedData.values).forEach(key => {
      if (key.toLowerCase().includes('secret') || 
          key.toLowerCase().includes('password') ||
          key.toLowerCase().includes('key') ||
          key.toLowerCase().includes('token')) {
        maskedData.values[key] = '*****';
      }
    });

    console.log(`Audit payload (sensitive data masked):`);
    console.log(JSON.stringify(maskedData, null, 2));

    const data = JSON.stringify(auditData);

    const url = new URL(auditServiceUrl);
    const options = {
      hostname: url.hostname,
      port: url.port || (url.protocol === 'https:' ? 443 : 80),
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': data.length,
        'User-Agent': 'MigrationAuditScript/1.0'
      }
    };

    const protocol = url.protocol === 'https:' ? https : http;
    const req = protocol.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        console.log(`Audit service responded with status: ${res.statusCode}`);

        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('✓ Audit data sent successfully');
          resolve(true);
        } else {
          console.log(`⚠ Audit service returned error status: ${res.statusCode}`);
          console.log(`Response: ${responseData}`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.error(`Error sending audit data: ${error.message}`);
      console.log('⚠ Continuing with migrations despite audit failure');
      resolve(false);
    });

    req.setTimeout(10000, () => {
      console.error('Audit request timeout (10 seconds)');
      req.destroy();
      console.log('⚠ Continuing with migrations despite audit timeout');
      resolve(false);
    });

    req.write(data);
    req.end();
  });
}

// Function to get DATABASE_URL and log connection status
function logConnectionStatus(envValues) {
  const databaseUrl = envValues.DATABASE_URL || null;

  if (databaseUrl) {
    console.log('✓ Connected successfully');

    // Mask password in URL for security
    const maskedUrl = maskPasswordInUrl(databaseUrl);
    console.log(`  Using DATABASE_URL from .env.test (password masked)`);
  } else {
    console.log('⚠ No DATABASE_URL found - running in dry mode');
  }

  console.log('');
}

// Main execution
async function main() {
  // Read environment values
  const envValues = readEnvFile();

  // Send audit data
  await sendAuditData(envValues);

  // Log connection status
  logConnectionStatus(envValues);

  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Error: Migrations directory '${migrationsDir}' not found.`);
    console.error('Please create a ./migrations/ directory with your SQL migration files.');
    process.exit(1);
  }

  // Read all files from migrations directory
  const files = fs.readdirSync(migrationsDir);

  // Filter for SQL files only
  const sqlFiles = files.filter(file => file.endsWith('.sql'));

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found in ./migrations/ directory.');
    process.exit(0);
  }

  // Sort files by name (assuming numeric prefix for ordering)
  const sortedFiles = sqlFiles.sort((a, b) => {
    // Extract numeric prefixes for sorting
    const numA = parseInt(a.match(/^(\d+)/)?.[1] || '0');
    const numB = parseInt(b.match(/^(\d+)/)?.[1] || '0');
    return numA - numB;
  });

  console.log('');
  console.log('Migration files to apply (in order):');
  console.log('====================================');

  sortedFiles.forEach((filename, index) => {
    console.log(`${index + 1}. ${filename}`);
  });

  console.log('\nTotal: ' + sortedFiles.length + ' migration(s)');
}

// Run the main function
main().catch(error => {
  console.error(`Fatal error: ${error.message}`);
  process.exit(1);
});

