#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */
class MigrationRunner {
  constructor() {
    this.migrationsDir = path.join(__dirname, 'migrations');
  }

  /**
   * Checks if the migrations directory exists
   * @returns {boolean} True if directory exists, false otherwise
   */
  checkMigrationsDir() {
    try {
      if (!fs.existsSync(this.migrationsDir)) {
        console.error(`❌ Migrations directory not found: ${this.migrationsDir}`);
        return false;
      }
      return true;
    } catch (error) {
      console.error(`❌ Error accessing migrations directory: ${error.message}`);
      return false;
    }
  }

  /**
   * Reads all files from the migrations directory
   * @returns {Array<string>} Array of filenames
   */
  readMigrationFiles() {
    try {
      const files = fs.readdirSync(this.migrationsDir);
      return files;
    } catch (error) {
      console.error(`❌ Error reading migrations directory: ${error.message}`);
      return [];
    }
  }

  /**
   * Filters and sorts SQL migration files
   * @param {Array<string>} files - Array of filenames
   * @returns {Array<string>} Sorted array of SQL filenames
   */
  filterAndSortMigrationFiles(files) {
    // Filter for SQL files
    const sqlFiles = files.filter(file => {
      return file.toLowerCase().endsWith('.sql');
    });

    // Sort files by name (assuming timestamp or numeric prefix)
    const sortedFiles = sqlFiles.sort((a, b) => {
      // Try to extract numeric prefixes for sorting
      const getPrefix = (filename) => {
        const match = filename.match(/^(\d+)[-_]/);
        return match ? parseInt(match[1]) : filename;
      };

      const prefixA = getPrefix(a);
      const prefixB = getPrefix(b);

      if (typeof prefixA === 'number' && typeof prefixB === 'number') {
        return prefixA - prefixB;
      }

      // If not numeric, sort alphabetically
      return a.localeCompare(b);
    });

    return sortedFiles;
  }

  /**
   * Displays migration plan
   * @param {Array<string>} migrationFiles - Sorted array of migration files
   */
  displayMigrationPlan(migrationFiles) {
    console.log('\n📋 Database Migration Plan\n');
    console.log('='.repeat(50));

    if (migrationFiles.length === 0) {
      console.log('No SQL migration files found in ./migrations/ directory.');
      console.log('='.repeat(50));
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    migrationFiles.forEach((filename, index) => {
      const migrationNumber = (index + 1).toString().padStart(3, '0');
      console.log(`${migrationNumber}. ${filename}`);

      try {
        const filePath = path.join(this.migrationsDir, filename);
        const stats = fs.statSync(filePath);
        const fileSize = (stats.size / 1024).toFixed(2); // Convert to KB

        // Read first few lines for preview
        const content = fs.readFileSync(filePath, 'utf8');
        const lines = content.split('\n').slice(0, 5).join('\n').trim();
        const preview = lines.length > 100 ? lines.substring(0, 100) + '...' : lines;

        console.log(`    📏 Size: ${fileSize} KB`);
        console.log(`    📄 Preview: ${preview}\n`);
      } catch (error) {
        console.log(`    ⚠️  Could not read file details: ${error.message}\n`);
      }
    });

    console.log('='.repeat(50));
    console.log(`\nTo apply these migrations, you would need to:\n`);
    console.log(`1. Connect to your database`);
    console.log(`2. Execute each SQL file in the order shown above`);
    console.log(`3. Track which migrations have been applied (usually in a migrations table)\n`);
  }

  /**
   * Main function to run the migration script
   */
  run() {
    console.log('🚀 Starting database migration analyzer...\n');

    // Check if migrations directory exists
    if (!this.checkMigrationsDir()) {
      process.exit(1);
    }

    // Read all files from migrations directory
    const files = this.readMigrationFiles();
    if (files.length === 0) {
      console.log('No files found in migrations directory.');
      process.exit(0);
    }

    // Filter and sort SQL files
    const migrationFiles = this.filterAndSortMigrationFiles(files);

    // Display migration plan
    this.displayMigrationPlan(migrationFiles);
  }
}

// If script is run directly (not imported as module)
if (require.main === module) {
  const migrationRunner = new MigrationRunner();
  migrationRunner.run();
}

// Export for programmatic use
module.exports = MigrationRunner;

-- Create posts table
CREATE TABLE IF NOT EXISTS posts (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    title VARCHAR(255) NOT NULL,
    content TEXT NOT NULL,
    slug VARCHAR(300) UNIQUE NOT NULL,
    status VARCHAR(20) DEFAULT 'draft',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    published_at TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Foreign key index
CREATE INDEX idx_posts_user_id ON posts(user_id);

-- Index for slug lookup
CREATE INDEX idx_posts_slug ON posts(slug);

-- Index for status filtering
CREATE INDEX idx_posts_status ON posts(status);

-- Index for published date ordering
CREATE INDEX idx_posts_published_at ON posts(published_at);

-- Create comments table
CREATE TABLE IF NOT EXISTS comments (
    id SERIAL PRIMARY KEY,
    post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    parent_id INTEGER REFERENCES comments(id) ON DELETE CASCADE,
    content TEXT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    is_approved BOOLEAN DEFAULT FALSE
);

-- Foreign key indexes
CREATE INDEX idx_comments_post_id ON comments(post_id);
CREATE INDEX idx_comments_user_id ON comments(user_id);
CREATE INDEX idx_comments_parent_id ON comments(parent_id);

-- Index for approved comments
CREATE INDEX idx_comments_is_approved ON comments(is_approved);

-- Index for chronological ordering
CREATE INDEX idx_comments_created_at ON comments(created_at);

