      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      // Extract DATABASE_URL
      if (trimmedLine.startsWith('DATABASE_URL=')) {
        this.databaseUrl = trimmedLine.substring('DATABASE_URL='.length).trim();

        // Remove surrounding quotes if present
        this.databaseUrl = this.databaseUrl.replace(/^['"]|['"]$/g, '');
        break;
      }
    }

    if (this.databaseUrl) {
      console.log(`✅ Loaded database configuration from ${this.envFile}`);
      return true;
    } else {
      console.warn(`⚠️  DATABASE_URL not found in ${this.envFile}`);
      console.log('   Proceeding without database connection configuration.\n');
      return false;
    }
  } catch (error) {
    console.error(`❌ Error reading environment file: ${error.message}`);
    return false;
  }
}

/**
 * Parse database URL and extract connection details
 * @returns {object|null} Connection details or null if parsing fails
 */
parseDatabaseUrl() {
  if (!this.databaseUrl) {
    return null;
  }

  try {
    const urlPattern = /^(?<protocol>[^:]+):\/\/(?:(?<username>[^:@]+)(?::(?<password>[^@]+))?@)?(?<host>[^:/]+)(?::(?<port>\d+))?\/(?<database>[^?]+)/;
    const match = this.databaseUrl.match(urlPattern);

    if (match) {
      const { protocol, username, password, host, port, database } = match.groups;

      // Create a masked URL for logging (hide password)
      const maskedUrl = password 
        ? `${protocol}://${username}:****@${host}${port ? ':' + port : ''}/${database}`
        : `${protocol}://${username}@${host}${port ? ':' + port : ''}/${database}`;

      return {
        protocol,
        username,
        hasPassword: !!password,
        host,
        port: port || (protocol === 'postgres' ? '5432' : '3306'),
