#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Test various DATABASE_URL formats
 */
class DatabaseUrlTester {
  constructor() {
    this.testDir = path.join(__dirname, 'test_envs');
  }

  createTestEnv(filename, content) {
    const filePath = path.join(this.testDir, filename);
    fs.writeFileSync(filePath, content, 'utf8');
    return filePath;
  }

  testUrlParsing() {
    console.log('🧪 Testing DATABASE_URL parsing...\n');

    const testCases = [
      {
        name: 'PostgreSQL with password',
        url: 'postgres://admin:secret123@localhost:5432/mydb',
        expected: {
          protocol: 'postgres',
          username: 'admin',
          hasPassword: true,
          host: 'localhost',
          port: '5432',
          database: 'mydb'
        }
      },
      {
        name: 'PostgreSQL without password',
        url: 'postgres://admin@localhost/mydb',
        expected: {
          protocol: 'postgres',
          username: 'admin',
          hasPassword: false,
          host: 'localhost',
          port: '5432', // default
          database: 'mydb'
        }
      },
      {
        name: 'MySQL with password',
        url: 'mysql://user:pass@db.example.com:3306/appdb',
        expected: {
          protocol: 'mysql',
          username: 'user',
          hasPassword: true,
          host: 'db.example.com',
          port: '3306',
          database: 'appdb'
        }
      },
      {
        name: 'With quotes',
        url: '"postgres://admin:secret@localhost:5432/mydb"',
        expected: {
          protocol: 'postgres',
          username: 'admin',
          hasPassword: true,
          host: 'localhost',
          port: '5432',
          database: 'mydb'
        }
      }
    ];

    // Extract parsing logic from migrate.js for testing
    const parseDatabaseUrl = (databaseUrl) => {
      if (!databaseUrl) {
        return null;
      }

      try {
        // Remove surrounding quotes if present
        const url = databaseUrl.replace(/^['"]|['"]$/g, '');

        const urlPattern = /^(?<protocol>[^:]+):\/\/(?:(?<username>[^:@]+)(?::(?<password>[^@]+))?@)?(?<host>[^:/]+)(?::(?<port>\d+))?\/(?<database>[^?]+)/;
        const match = url.match(urlPattern);

        if (match) {
          const { protocol, username, password, host, port, database } = match.groups;

          return {
            protocol,
            username,
            hasPassword: !!password,
            host,
            port: port || (protocol === 'postgres' ? '5432' : '3306'),
            database,
            maskedUrl: password 
              ? `${protocol}://${username}:****@${host}${port ? ':' + port : ''}/${database}`
              : `${protocol}://${username}@${host}${port ? ':' + port : ''}/${database}`
          };
        }

        return null;
      } catch (error) {
        console.warn(`⚠️  Could not parse DATABASE_URL: ${error.message}`);
        return null;
      }
    };

    let passed = 0;
    let failed = 0;

    testCases.forEach((testCase, index) => {
      console.log(`Test ${index + 1}: ${testCase.name}`);
      console.log(`   URL: ${testCase.url}`);

      const result = parseDatabaseUrl(testCase.url);

      if (result) {
        let success = true;
        for (const key in testCase.expected) {
          if (result[key] !== testCase.expected[key]) {
            console.log(`   ❌ ${key}: Expected "${testCase.expected[key]}", Got "${result[key]}"`);
            success = false;
          }
        }

        if (success) {
          console.log(`   ✅ Parsed successfully`);
          console.log(`      Protocol: ${result.protocol}, Host: ${result.host}:${result.port}`);
          console.log(`      Database: ${result.database}, Username: ${result.username}`);
          console.log(`      Has password: ${result.hasPassword}\n`);
          passed++;
        } else {
          failed++;
        }
      } else {
        console.log(`   ❌ Failed to parse\n`);
        failed++;
      }
    });

    console.log(`\n📊 Results: ${passed} passed, ${failed} failed`);
  }

  cleanup() {
    if (fs.existsSync(this.testDir)) {
      fs.rmSync(this.testDir, { recursive: true });
    }
  }
}

// Run tests
const tester = new DatabaseUrlTester();
tester.testUrlParsing();
tester.cleanup();

