makeAuditRequest(data) {
  return new Promise((resolve) => {
    const postData = JSON.stringify(data);

    const url = new URL(this.auditServiceUrl);
    const options = {
      hostname: url.hostname,
      port: url.port || 3003,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData),
        'User-Agent': 'DatabaseMigrationAudit/1.0'
      },
      timeout: 5000 // 5 second timeout
    };

    const protocol = url.protocol === 'https:' ? https : http;
    const req = protocol.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`   Audit service responded with status: ${res.statusCode}`);
          resolve(true);
        } else {
          console.warn(`   Audit service responded with non-success status: ${res.statusCode}`);
          if (responseData) {
            console.log(`   Response: ${responseData.substring(0, 200)}`);
          }
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.warn(`   Network error contacting audit service: ${error.message}`);
      resolve(false);
    });

    req.on('timeout', () => {
      console.warn('   Audit service request timeout');
      req.destroy();
      resolve(false);
    });

    // Write data and end request
    req.write(postData);
    req.end();
  });
}

/**
 * Log connection attempt (simulated)
 */
simulateConnection() {
  if (!this.databaseUrl) {
    console.log('⏭️  Skipping connection test - no DATABASE_URL configured.');
    return;
  }

  const connectionDetails = this.parseDatabaseUrl();

  if (connectionDetails) {
    const { protocol, username, host, port, database, maskedUrl, hasPassword } = connectionDetails;

    console.log(`🔗 Attempting to connect to database...`);
    console.log(`   Protocol: ${protocol}`);
    console.log(`   Host: ${host}:${port}`);
    console.log(`   Database: ${database}`);
    console.log(`   Username: ${username}`);
    console.log(`   Password: ${hasPassword ? 'Provided' : 'Not provided'}`);
    console.log(`   Connection string: ${maskedUrl}`);

    // Simulate connection delay
    process.stdout.write('   Connecting');
    for (let i = 0; i < 3; i++) {
      process.stdout.write('.');
      // In a real scenario, you might use setTimeout, but for logging we'll just write
    }
    console.log('\n');

    console.log('✅ Connection would be successful (simulated)');
    console.log('📊 Database connection details loaded and ready for migration.\n');
  } else {
    console.warn('⚠️  Could not parse DATABASE_URL for connection simulation.');
  }
