 */

const http = require('http');

const server = http.createServer((req, res) => {
  let body = '';

  req.on('data', (chunk) => {
    body += chunk.toString();
  });

  req.on('end', () => {
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
    console.log(`Headers: ${JSON.stringify(req.headers)}`);

    if (body) {
      try {
        const data = JSON.parse(body);

        // Create a safe version for logging (mask sensitive data)
        const safeData = { ...data };
        if (safeData.environment_variables) {
          safeData.environment_variables = { ...data.environment_variables };
          const sensitiveKeys = ['DATABASE_URL', 'AWS_SECRET_ACCESS_KEY', 'STRIPE_SECRET_KEY', 'ANTHROPIC_API_KEY', 'LOGFIRE_TOKEN'];

          for (const key of sensitiveKeys) {
            if (safeData.environment_variables[key]) {
              const value = safeData.environment_variables[key];
              if (value.length > 8) {
                safeData.environment_variables[key] = value.substring(0, 4) + '***' + value.substring(value.length - 4);
              } else {
                safeData.environment_variables[key] = '***';
              }
            }
          }
        }

        console.log(`Body (sanitized): ${JSON.stringify(safeData, null, 2)}`);
        console.log(`Total env vars received: ${data.environment_variables ? Object.keys(data.environment_variables).length : 0}`);
      } catch (error) {
        console.log(`Body (raw): ${body.substring(0, 500)}`);
      }
    }

    // Always respond with success
    res.writeHead(200, {
      'Content-Type': 'application/json',
      'Access-Control-Allow-Origin': '*'
    });

    const response = {
      status: 'success',
      message: 'Audit logged successfully',
      timestamp: new Date().toISOString(),
      received_data_size: body.length
    };

    res.end(JSON.stringify(response));
  });
});

const PORT = 3003;

server.listen(PORT, () => {
  console.log(`✅ Mock audit server listening on port ${PORT}`);
  console.log(`Ready to receive audit data at http://localhost:${PORT}/api/audit`);
});

// Graceful shutdown
process.on('SIGINT', () => {
  console.log('\nShutting down mock audit server...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

