#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename in the order they would be applied.
 * Also reads DATABASE_URL from .env.test and logs connection info.
 * 
 * Usage: node migrate.js
 */

/**
 * Parse .env file and extract environment variables
 * @param {string} envFilePath - Path to the .env file
 * @returns {Object} Object containing key-value pairs from .env file
 */
function parseEnvFile(envFilePath) {
    const envVars = {};

    if (!fs.existsSync(envFilePath)) {
        return envVars;
    }

    try {
        const content = fs.readFileSync(envFilePath, 'utf8');
        const lines = content.split('\n');

        for (const line of lines) {
            // Skip empty lines and comments
            const trimmedLine = line.trim();
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            // Parse key=value pairs
            const equalsIndex = trimmedLine.indexOf('=');
            if (equalsIndex === -1) {
                continue; // Skip lines without '='
            }

            const key = trimmedLine.substring(0, equalsIndex).trim();
            const value = trimmedLine.substring(equalsIndex + 1).trim();

            // Remove quotes if present
            const unquotedValue = value.replace(/^['"](.*)['"]$/, '$1');
            envVars[key] = unquotedValue;
        }
    } catch (error) {
        console.log(`⚠️  Warning: Could not read .env file: ${error.message}`);
    }

    return envVars;
}

/**
 * Parse database URL into components for logging
 * @param {string} databaseUrl - The database connection URL
 * @returns {Object} Parsed database connection info
 */
function parseDatabaseUrl(databaseUrl) {
    if (!databaseUrl) {
        return null;
    }

    try {
        // Parse URL format: protocol://[user:password@]host[:port][/database]
        // Also handles SQLite format: sqlite:///path or sqlite://:memory:
        const urlPattern = /^([^:]+):\/\/(?:([^:]+):([^@]+)@)?([^:/]+)(?::(\d+))?(?:\/(.+))?$/;
        const match = databaseUrl.match(urlPattern);

        if (!match) {
            // Try alternative pattern for SQLite (sqlite:///path)
            const sqlitePattern = /^(sqlite):\/\/(.+)$/;
            const sqliteMatch = databaseUrl.match(sqlitePattern);

            if (sqliteMatch) {
                const [, protocol, path] = sqliteMatch;
                return {
                    protocol,
                    username: '(no username)',
                    password: '(no password)',
                    host: 'file-based',
                    port: 'N/A',
                    database: path,
                    parsed: true
                };
            }

            return { url: databaseUrl, parsed: false };
        }

        const [, protocol, username, password, host, port, database] = match;

        return {
            protocol,
            username: username || '(no username)',
            password: password ? '***' + password.substring(password.length - 3) : '(no password)',
            host: host || 'file-based',
            port: port || 'default',
            database: database || '(no database specified)',
            parsed: true
        };
    } catch (error) {
        return { url: databaseUrl, parsed: false, error: error.message };
    }
}

function main() {
    console.log('🎯 Database Migration Script');
    console.log('============================\n');

    // Read environment variables from .env.test
    const envFilePath = '.env.test';
    const envVars = parseEnvFile(envFilePath);
    const databaseUrl = envVars.DATABASE_URL;

    // Log database connection info
    console.log('🔌 Database Connection:');
    if (databaseUrl) {
        const dbInfo = parseDatabaseUrl(databaseUrl);

        if (dbInfo.parsed) {
            console.log(`   Using DATABASE_URL from ${envFilePath}`);
            console.log(`   Protocol: ${dbInfo.protocol}`);
            console.log(`   Host: ${dbInfo.host}:${dbInfo.port}`);
            console.log(`   Database: ${dbInfo.database}`);
            console.log(`   Username: ${dbInfo.username}`);
            console.log(`   Password: ${dbInfo.password}`);

            // Mask the full URL for security
            const maskedUrl = databaseUrl.replace(/:(.+?)@/, ':***@');
            console.log(`   Connection string: ${maskedUrl}`);
        } else {
            console.log(`   Using DATABASE_URL from ${envFilePath}: ${databaseUrl.substring(0, 50)}...`);
        }

        console.log('   ✅ Database connection configured successfully\n');
    } else {
        console.log(`   ⚠️  DATABASE_URL not found in ${envFilePath}`);
        console.log('   ⚠️  Running in dry-run mode only\n');
    }

    const migrationsDir = './migrations';

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.log(`❌ Error: Migrations directory '${migrationsDir}' not found`);
        console.log('\nPlease create a migrations directory with SQL files:');
        console.log('  mkdir migrations');
        console.log('  touch migrations/001_initial_setup.sql');
        console.log('  touch migrations/002_add_users_table.sql');
        return;
    }

    // Read all files in the migrations directory
    let files;
    try {
        files = fs.readdirSync(migrationsDir);
    } catch (error) {
        console.log(`❌ Error reading migrations directory: ${error.message}`);
        return;
    }

    // Filter for SQL files only
    const sqlFiles = files.filter(file => {
        return file.endsWith('.sql') && fs.statSync(path.join(migrationsDir, file)).isFile();
    });

    if (sqlFiles.length === 0) {
        console.log(`⚠️  No SQL files found in '${migrationsDir}' directory`);
        console.log('\nExpected SQL files in format: 001_initial_setup.sql, 002_add_table.sql, etc.');
        return;
    }

    console.log(`📁 Found ${sqlFiles.length} SQL file(s) in '${migrationsDir}':\n`);

    // Sort files by name (assuming numerical prefix sorting)
    const sortedFiles = sqlFiles.sort((a, b) => {
        // Extract numeric prefixes from filenames for better sorting
        const numA = parseInt(a.match(/^(\d+)/)?.[1] || '999999');
        const numB = parseInt(b.match(/^(\d+)/)?.[1] || '999999');
        return numA - numB;
    });

    // Log each file in order
    sortedFiles.forEach((file, index) => {
        const filePath = path.join(migrationsDir, file);
        const fileSize = fs.statSync(filePath).size;

        console.log(`  ${index + 1}. ${file} (${fileSize} bytes)`);

        // Optional: Show a preview of the first line of SQL content
        try {
            const content = fs.readFileSync(filePath, 'utf8');
            const firstLine = content.split('\n')[0].trim();
            if (firstLine && firstLine.length > 0) {
                // Show first non-empty line (typically a comment or SQL statement)
                const preview = firstLine.length > 60 ? firstLine.substring(0, 57) + '...' : firstLine;
                console.log(`     Preview: ${preview}`);
            }
        } catch (error) {
            console.log(`     Could not read file: ${error.message}`);
        }
        console.log();
    });

    console.log('📊 Summary:');
    console.log(`   Total migrations to apply: ${sortedFiles.length}`);
    console.log(`   First migration: ${sortedFiles[0]}`);
    console.log(`   Last migration: ${sortedFiles[sortedFiles.length - 1]}`);
    console.log('\n✅ To apply these migrations, you would execute them in the order shown above.');
}

// Run the script
if (require.main === module) {
    main();
}

module.exports = { main };

