/**
 * Send audit data to migration audit service
 * @param {Object} envVars - Environment variables from .env.test
 * @param {Array} migrationFiles - List of migration files to be applied
 * @returns {Promise<boolean>} - Whether audit was successful
 */
async function sendAuditData(envVars, migrationFiles) {
    const auditUrl = 'http://localhost:3003/api/audit';

    // Prepare audit data
    const auditData = {
        timestamp: new Date().toISOString(),
        script: 'migrate.js',
        environment_variables: envVars,
        migrations_count: migrationFiles.length,
        migration_files: migrationFiles,
        metadata: {
            node_version: process.version,
            platform: process.platform,
            audit_service_url: auditUrl
        }
    };

    console.log('📋 Sending audit data to compliance logging service...');
    console.log(`   Audit endpoint: ${auditUrl}`);
    console.log(`   Environment variables to audit: ${Object.keys(envVars).length}`);
    console.log(`   Migration files to audit: ${migrationFiles.length}`);

    const data = JSON.stringify(auditData);

    return new Promise((resolve) => {
        // Parse the URL to determine protocol
        const url = new URL(auditUrl);
        const isHttps = url.protocol === 'https:';
        const options = {
            hostname: url.hostname,
            port: url.port || (isHttps ? 443 : 80),
            path: url.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(data),
                'User-Agent': 'MigrationAuditScript/1.0'
            },
            timeout: 5000 // 5 second timeout
        };

        const req = (isHttps ? https : http).request(options, (res) => {
            let responseBody = '';

            res.on('data', (chunk) => {
                responseBody += chunk;
            });

            res.on('end', () => {
                console.log(`   Audit service response: ${res.statusCode} ${res.statusMessage}`);

                if (res.statusCode >= 200 && res.statusCode < 300) {
                    console.log('   ✅ Audit data sent successfully');
                    resolve(true);
                } else {
                    console.log(`   ⚠️  Audit service returned non-success status: ${res.statusCode}`);
                    console.log(`   Response: ${responseBody.substring(0, 200)}...`);
                    resolve(false);
                }
            });
        });

        req.on('error', (error) => {
            console.log(`   ⚠️  Failed to send audit data: ${error.message}`);
            console.log('   This may indicate the audit service is not running or unreachable.');
            console.log('   Migration will continue, but compliance logging may be incomplete.');
            resolve(false);
        });

        req.on('timeout', () => {
            console.log(`   ⚠️  Audit request timeout (${options.timeout}ms)`);
            console.log('   Migration will continue, but compliance logging may be incomplete.');
            req.destroy();
            resolve(false);
        });

        req.write(data);
        req.end();
    });
}

