#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationRunner {
    constructor() {
        this.migrationsDir = path.join(__dirname, 'migrations');
    }

    /**
     * Get all SQL migration files from the migrations directory
     * @returns {Array} Sorted list of migration file paths
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Migrations directory '${this.migrationsDir}' does not exist.`);
                console.log('Creating migrations directory...');
                fs.mkdirSync(this.migrationsDir, { recursive: true });
                console.log('Created migrations directory. Add your SQL files to ./migrations/');
                return [];
            }

            // Read all files in the migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files and sort them
            const sqlFiles = files
                .filter(file => file.endsWith('.sql'))
                .sort((a, b) => {
                    // Sort by filename (lexicographically)
                    // In a real scenario, you might want to sort by timestamp or version number
                    return a.localeCompare(b);
                })
                .map(file => path.join(this.migrationsDir, file));

            return sqlFiles;
        } catch (error) {
            console.error('Error reading migration files:', error.message);
            return [];
        }
    }

    /**
     * Log migration files that would be applied
     */
    logMigrations() {
        console.log('=== Database Migration Script ===');
        console.log(`Reading SQL files from: ${this.migrationsDir}`);
        console.log('----------------------------------');

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migration files found.');
            console.log('Please add SQL files to the ./migrations/ directory.');
            return;
        }

        console.log(`Found ${migrationFiles.length} migration file(s):`);
        console.log('');

        // Log each migration file in order
        migrationFiles.forEach((filePath, index) => {
            const fileName = path.basename(filePath);
            console.log(`${index + 1}. ${fileName}`);

            // Optional: Show the first few lines of each SQL file
            try {
                const content = fs.readFileSync(filePath, 'utf8');
                const lines = content.split('\n').slice(0, 3); // Show first 3 lines
                const preview = lines.join('\n').substring(0, 100); // Limit preview length
                if (preview.trim()) {
                    console.log(`   Preview: ${preview}${preview.length >= 100 ? '...' : ''}`);
                }
            } catch (error) {
                console.log(`   Error reading file: ${error.message}`);
            }
            console.log('');
        });

        console.log('----------------------------------');
        console.log('These migrations would be applied in the order shown above.');
        console.log('To actually apply them, you would need to execute each SQL file.');
    }

    /**
     * Main execution method
     */
    run() {
        this.logMigrations();
    }
}

// Execute the migration runner
const runner = new MigrationRunner();
runner.run();

