#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationRunner {
    constructor() {
        this.migrationsDir = path.join(__dirname, 'migrations');
        this.envFile = path.join(__dirname, '.env.test');
        this.databaseUrl = null;
    }

    /**
     * Read DATABASE_URL from .env.test file
     * @returns {string|null} Database URL or null if not found
     */
    readDatabaseUrl() {
        try {
            if (!fs.existsSync(this.envFile)) {
                console.error(`Environment file '${this.envFile}' not found.`);
                return null;
            }

            const envContent = fs.readFileSync(this.envFile, 'utf8');
            const lines = envContent.split('\n');

            for (const line of lines) {
                const trimmedLine = line.trim();
                // Skip empty lines and comments
                if (!trimmedLine || trimmedLine.startsWith('#')) {
                    continue;
                }

                // Parse key=value pairs
                const match = trimmedLine.match(/^DATABASE_URL=(.+)$/);
                if (match) {
                    return match[1].trim();
                }
            }

            console.error('DATABASE_URL not found in .env.test file');
            return null;
        } catch (error) {
            console.error(`Error reading .env.test file: ${error.message}`);
            return null;
        }
    }

    /**
     * Log connection message (simulated connection)
     */
    logConnection() {
        console.log('=== Database Migration Script ===');

        this.databaseUrl = this.readDatabaseUrl();

        if (this.databaseUrl) {
            // Parse database URL to extract connection info (for logging)
            try {
                const url = new URL(this.databaseUrl);
                const host = url.hostname;
                const port = url.port || '5432'; // Default PostgreSQL port
                const database = url.pathname.substring(1); // Remove leading slash

                console.log(`✓ Connected to database: ${database} at ${host}:${port}`);
                console.log('✓ Connection established successfully');
            } catch (error) {
                console.log(`✓ Using DATABASE_URL: ${this.databaseUrl.substring(0, 50)}...`);
                console.log('✓ Connection established successfully');
            }
        } else {
            console.log('⚠️  No DATABASE_URL found - running in dry mode');
            console.log('⚠️  Add DATABASE_URL to .env.test to enable database operations');
        }

        console.log('----------------------------------');
    }

